window.KG_BRIEF = [{"id": 1, "date": "2026-11-01", "title": "每日世界简报 · 2026-11-01", "summary": "以色列组阁卡死 · 俄乌打电网 · 从严治党《决定》 · 三季报净利5.1万亿创新高", "author": "聪明仔", "items": [{"cat": "国际", "t": "以色列组阁又卡死", "b": "事实：11月1日总统赫尔佐格宣布，11月4日从中央选举委员会主席手中接收正式选举结果，随即在总统官邸启动组阁磋商，呼吁各党派直面选举结果、避免再选一轮。逻辑：议会席位碎片化后小党成了\"造王者\"，谁先让步谁掉选票，僵局反而成了抬价筹码。历史：2019—2021年以色列两年内四次大选、组阁两次超期，僵局政治反复上演。影响：中东政策进入空转期，普通人关注油价与地区风险溢价即可，不必追单条地缘消息。", "src": "央视新闻 / 赫尔佐格办公室表态", "s": "大选又卡死，总统喊各党妥协", "topic": "国际"}, {"cat": "国际", "t": "俄乌互打能源设施", "b": "事实：乌方称俄袭击致8个州断电、数十万人受影响；克宫称首轮谈判应为俄美乌三方，普京从未拒绝对话；双方同意定期开展人道救援。逻辑：打电网就是削冬季民生与战争意志，同时把谈判筹码抬到最高再上桌。历史：2022—2023年冬季俄持续打击乌电力系统，乌靠西方抢修设备勉强维持。影响：欧洲气价电价冬季更敏感，会传导到国内成品油与化工品，加油可能慢慢变贵。", "src": "央视新闻 / 路透社", "s": "8州断电，克宫提三方谈判", "topic": "国际"}, {"cat": "国际", "t": "伊朗把英海空军列为\"恐怖组织\"", "b": "事实：11月1日伊朗外交部宣布该决定；特朗普称美国还需\"处理\"伊朗一两个目标；美官员称若中期选举惨败或更倾向再袭。逻辑：把对手军队\"恐怖组织化\"是为将来行动预置合法性，也给国内强硬派交差。历史：2019年美国把伊朗革命卫队列为恐怖组织，伊方随即对等反制。影响：波斯湾航运保费与油价风险溢价上行，最终反映到油价上。", "src": "金十数据 / 伊朗外交部声明", "s": "把英海空军列为\"恐怖组织\"", "topic": "国际"}, {"cat": "国内·政策", "t": "从严治党《决定》发布", "b": "事实：中共中央发布《关于持之以恒推进全面从严治党若干重大问题的决定》，习近平作说明；此前党的二十届五中全会审议通过该决定。逻辑：新五年周期开局先定组织纪律与作风基调，为后面的人事与政策落地清路。历史：2016年十八届六中全会定党内政治生活准则，随后巡视全覆盖。影响：地方\"求稳\"倾向上升，项目审批节奏可能放缓。", "src": "新华社 / 二十届五中全会公报", "s": "中央发布《决定》，习近平说明", "topic": "政策"}, {"cat": "国内·政策", "t": "三部门明日开会研究资本市场工具", "b": "事实：央行、金融监管总局、证监会11月2日召开会议（座谈会），研究推动支持资本市场工具的使用。逻辑：三季报亮眼而指数在跌，监管想稳预期，不是直接托指数。历史：2024年9月三部门联合发布会后，推出互换便利与回购增持再贷款。影响：关注是否加码回购增持再贷款额度；对持股者是情绪面利好，不构成买点。", "src": "财联社（座谈会通知）", "s": "央行金监证监研究资本市场工具", "topic": "股票"}, {"cat": "国内·民生", "t": "11月新规施行，法定假期增至13天", "b": "事实：11月起一批新规施行；法定放假总数已增至13天，成为热搜话题。逻辑：多放假是成本最低的扩内需，直接转化为服务消费，而不是发补贴。历史：2025年起法定节假日由11天增至13天（增除夕、5月2日）。影响：文旅、餐饮、航空受益；错峰出行比挤黄金周划算得多。", "src": "中国政府网 / 人社部", "s": "一批新规施行，法定假期增至13天", "topic": "民生"}, {"cat": "国内·民生", "t": "青岛熏硫白芷被立案", "b": "事实：央视《每周质量报告》曝光青岛抚顺路批发市场两家商户销售二氧化硫残留超标白芷，市场监管部门会同公安查封扣押、抽样送检并立案，另排查市场内23家经营户。逻辑：二氧化硫残留是干货老问题，曝光后快速处置是标准动作，关键看后续是否真处罚、是否全链条抽检。历史：2019年多地查出硫磺熏蒸八角、山药，均以专项整治收场，风头过后易反弹。影响：干货短期抽检加严，买白芷、八角认准正规渠道，别挑颜色特别白的。", "src": "央视《每周质量报告》 / 青岛市市场监管局通报", "s": "央视曝光，市监查封立案调查", "topic": "民生"}, {"cat": "国内·生活", "t": "流感季提前，北方大风", "b": "事实：中疾控称今年流感季提前并发布防治8问8答；中央气象台继续发大风蓝色预警，内蒙中西部、山西北部、河北北部、北京西部阵风8—9级。逻辑：高峰前移与骤降温、室内聚集叠加有关，不是病毒突然变强。历史：2023年秋冬季流感高峰提前到11月，多地儿科门诊爆满。影响：老人小孩尽早接种；北方注意高空坠物与森林火险。", "src": "中国疾控中心 / 中央气象台", "s": "中疾控发8问8答，北方阵风8-9级", "topic": "天气"}, {"cat": "科技", "t": "海阳核电三期开工", "b": "事实：山东海阳核电基地三期工程开工，投运后可满足约5400万人全年生活用电。逻辑：核电是零碳基荷电源，叠加AI算力用电激增，沿海核电进入批量核准期。历史：2011年福岛事故后审批停滞近4年，2015年重启，2019年后年均核准约10台。影响：核电设备与建安订单放量，对长期电价是压舱石。", "src": "国家能源局 / 山东核电", "s": "可满足5400万人全年生活用电", "topic": "能源"}, {"cat": "科技", "t": "2030年前实现载人登月", "b": "事实：我国计划2030年前载人登月，采用\"两次发射、一次登月\"：两枚长征十号分别送着陆器与飞船，环月交会对接。逻辑：分两次发射能降低单发风险与运力门槛，是务实路线而非炫技。历史：阿波罗靠土星五号单发直飞；苏联N1火箭四次试射全败。影响：航天产业链中长期受益，短线多为情绪炒作。", "src": "中国载人航天工程办公室", "s": "\"两次发射、一次登月\"方案", "topic": "科技"}, {"cat": "财经", "t": "三季报净利5.1万亿，创四年新高", "b": "事实：沪深5224家前三季营收56.6万亿（+5.8%）、净利5.1万亿（+8.5%），73%盈利；科创板三季度净利875.7亿（+455%），研发投入1471亿（+25.8%）。逻辑：改善来自低基数、AI硬件链和资源品；指数却在跌，是估值在杀，不是业绩在杀。历史：2022年三季报增速转负后，市场又用了两个季度才见底。影响：沪深300前向PE跌破十年均值、股息率3.4%，估值有底但缺催化。", "src": "沪深交易所三季报统计", "s": "净利5.1万亿，创四年新高", "topic": "股票"}, {"cat": "财经", "t": "金价跌回一年前，车市继续分化", "b": "事实：金价大跌回一年前，积压半年的婚嫁需求集中释放；10月车市比亚迪49.02万辆（+11%）、零跑10.61万辆（+51%）、小鹏5.02万辆创新高、理想2.9万辆、赛力斯-50%、长城-15.9%。逻辑：金价回落带动刚需补库，消费属性回归；车市进入强者恒强、价格战收尾阶段。历史：2013年金价暴跌引发\"中国大妈\"抢金，随后套牢数年。影响：别把抢金饰当抄底（有工费溢价）；车企看渗透率和出口，别看单月。提示：北美已进冬令时，明起美股22:30开盘（北京时间）。", "src": "上海黄金交易所 / 乘联会月度数据", "s": "金价跌回一年前，车企销量分化", "topic": "黄金"}, {"cat": "涨知识", "t": "1984年11月1日：邓小平提出裁军100万", "b": "事实：邓小平在中央军委座谈会上提出裁减军队员额100万，1985年正式宣布，1987年完成。逻辑：让国防建设为经济建设让路，腾出的财力投向教育与基建，是改革开放关键的一步\"减法\"。历史：同期美苏军备竞赛正酣，中国反向裁军被称为\"单方面和平姿态\"。影响：军费占财政比重大幅下降；大国战略往往先做减法再做加法。", "src": "人民网·党史频道", "s": "1984年邓小平提出裁军100万", "topic": "历史"}], "text": "《每日世界简报》 2026-11-01（周日）\n\n① 以色列组阁    大选又卡死，总统喊各党妥协\n② 俄乌能源战    8州断电，克宫提三方谈判\n③ 伊朗vs英国    把英海空军列为\"恐怖组织\"\n④ 从严治党决定    中央发布《决定》，习近平说明\n⑤ 三部门明日开会    央行金监证监研究资本市场工具\n⑥ 11月新规    一批新规施行，法定假期增至13天\n⑦ 青岛熏硫白芷    央视曝光，市监查封立案调查\n⑧ 流感提前+大风    中疾控发8问8答，北方阵风8-9级\n⑨ 海阳核电三期    可满足5400万人全年生活用电\n⑩ 2030年前登月    \"两次发射、一次登月\"方案\n⑪ 三季报    净利5.1万亿，创四年新高\n⑫ 金价+车市    金价跌回一年前，车企销量分化\n⑬ 历史上的今天    1984年邓小平提出裁军100万\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━━\n\n① 以色列组阁又卡死\n 事实 ｜ 11/1 总统赫尔佐格宣布 11/4 接收\n 正式选举结果，随即启动组阁磋商，\n 呼吁各党直面结果、避免再选一轮。\n 逻辑 ｜ （推演）议会碎片化后小党成\"造\n 王者\"，谁先让步谁掉选票，僵局反成筹码。\n 历史 ｜ 2019—2021 以色列两年四选，\n 组阁两次超期，僵局政治反复上演。\n 影响 ｜ 中东政策进入空转期；普通人关注油价\n 与地区风险溢价，不必追地缘消息。\n\n② 俄乌互打能源设施\n 事实 ｜ 乌称俄袭击致 8 州断电、数十万人；\n 克宫称首轮谈判应为俄美乌三方、\n 普京从未拒绝对话；双方同意定期人道救援。\n 逻辑 ｜ （推演）打电网＝削冬季民生与战争\n 意志，同时把谈判筹码抬到最高再上桌。\n 历史 ｜ 2022—2023 冬季俄持续打击乌电力，\n 乌靠西方抢修设备勉强维持。\n 影响 ｜ 欧洲气价电价在冬季更敏感；传导到国内\n 成品油与化工品，加油可能慢慢变贵。\n\n③ 伊朗把英海空军列为\"恐怖组织\"\n 事实 ｜ 11/1 伊朗外交部宣布该决定；\n 特朗普称美国还需\"处理\"伊朗一两个目标；\n 美官员称若中期选举惨败或更倾向再袭。\n 逻辑 ｜ （推演）把对手军队\"恐怖组织化\"＝\n 为将来行动预置合法性，也给国内强硬派交差。\n 历史 ｜ 2019 年美国把伊朗革命卫队列为恐怖\n 组织，伊方随即对等反制。\n 影响 ｜ 波斯湾航运保费与油价风险溢价上行，\n 最终会反映到油价上。\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━━━━\n\n④ 从严治党《决定》发布\n 事实 ｜ 中共中央发布《关于持之以恒推进全\n 面从严治党若干重大问题的决定》，\n 习近平作说明；二十届五中全会作出决定。\n 逻辑 ｜ （推演）新五年周期开局先定组织纪律，\n 为后面的人事与政策落地清路。\n 历史 ｜ 2016 年十八届六中全会定党内政治生\n 活准则，随后巡视全覆盖。\n 影响 ｜ 地方\"求稳\"倾向上升，项目审批节奏\n 可能放缓，做工程、材料生意的要留意。\n\n⑤ 三部门明日开会\n 事实 ｜ 央行、金融监管总局、证监会 11/2\n 召开会议（座谈会），研究推动支持\n 资本市场工具的使用。\n 逻辑 ｜ （推演）三季报亮眼而指数在跌，\n 监管想稳预期，不是直接托指数。\n 历史 ｜ 2024 年 9 月三部门联合发布会后，\n 推出互换便利与回购增持再贷款。\n 影响 ｜ 关注是否加码回购增持再贷款额度；\n 对持股者来说这是情绪面利好，不构成买点。\n\n⑥ 11月新规+假期13天\n 事实 ｜ 11 月起一批新规施行；法定放假总\n 数已增至 13 天（热搜在讨论）。\n 逻辑 ｜ （推演）多放假是成本最低的扩内需，\n 直接转化为服务消费，而不是发补贴。\n 历史 ｜ 2025 年起法定节假日由 11 天增至\n 13 天（增除夕、5 月 2 日）。\n 影响 ｜ 文旅、餐饮、航空受益；错峰出行\n 比挤在黄金周出行划算得多。\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━━━━\n\n⑦ 青岛熏硫白芷立案\n 事实 ｜ 央视《每周质量报告》曝光青岛抚顺\n 路批发市场两家商户售熏硫白芷，市监\n 查封扣押、抽样送检并立案，另排查 23 家。\n 逻辑 ｜ （推演）二氧化硫残留是干货老问题，\n 曝光→地方快速处置是标准动作，重点在\n 后续是否真处罚、是否全链条抽检。\n 历史 ｜ 2019 年多地查出硫磺熏蒸八角、山药，\n 均以专项整治收场，风头过后容易反弹。\n 影响 ｜ 干货短期抽检加严；买白芷、八角\n 要认准正规渠道，别挑颜色特别白的。\n\n⑧ 流感提前，北方大风\n 事实 ｜ 中疾控称今年流感季提前，发布防治\n 8 问 8 答；中央气象台 11/1 继续发大风\n 蓝色预警，内蒙中西部、山西北部、河北\n 北部、北京西部阵风 8—9 级。\n 逻辑 ｜ （推演）高峰前移与骤降温、室内\n 聚集叠加有关，不是病毒突然变强。\n 历史 ｜ 2023 年秋冬季流感高峰提前到 11 月，\n 多地儿科门诊爆满。\n 影响 ｜ 老人小孩尽早接种；北方注意高空\n 坠物、森林火险，阳台东西收进来。\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━━━━\n\n⑨ 海阳核电三期开工\n 事实 ｜ 山东海阳核电基地三期工程开工，\n 投运后可满足约 5400 万人全年生活用电。\n 逻辑 ｜ （推演）核电是零碳基荷电源，叠加\n AI 算力用电激增，沿海核电进入批量核准期。\n 历史 ｜ 2011 福岛后审批停滞近 4 年，2015\n 重启，2019 年后年均核准约 10 台。\n 影响 ｜ 核电设备与建安订单放量；对长期\n 电价是压舱石。\n\n⑩ 2030年前载人登月\n 事实 ｜ 我国计划 2030 年前实现载人登月，\n 采用\"两次发射、一次登月\"：两枚长征\n 十号分别送着陆器与飞船，环月交会对接。\n 逻辑 ｜ （推演）分两次发射能降低单发风险\n 与运力门槛，是务实路线而非炫技。\n 历史 ｜ 阿波罗靠土星五号单发直飞；苏联\n N1 火箭四次试射全败。\n 影响 ｜ 航天产业链（发动机、着陆器、测控）\n 中长期受益，短线多为情绪炒作。\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━━━━\n\n⑪ 三季报净利5.1万亿\n 事实 ｜ 沪深 5224 家前三季营收 56.6 万亿\n (+5.8%)、净利 5.1 万亿(+8.5%)，73% 盈利；\n 科创板 Q3 净利 875.7 亿(+455%)，研发\n 投入 1471 亿(+25.8%)。\n 逻辑 ｜ （推演）改善来自低基数、AI硬件链\n 和资源品，指数却在跌，是估值在杀，业绩没杀。\n 历史 ｜ 2022 年三季报增速转负后，市场又\n 用了两个季度才见底，业绩不等于底部到了。\n 影响 ｜ 沪深 300 前向 PE 跌破十年均值、\n 股息率 3.4%，估值有底但缺催化，别急。\n\n⑫ 金价跌回一年前、车市分化\n 事实 ｜ 金价大跌回一年前，积压半年的婚嫁\n 需求集中释放，有人提前买 30g 金饰过年；\n 10 月车市：比亚迪 49.02 万(+11%)、零跑\n 10.61 万(+51%)、小鹏 5.02 万创新高、\n 理想 2.9 万、赛力斯 -50%、长城 -15.9%。\n 逻辑 ｜ （推演）金价回落带动刚需补库，说明\n 消费属性回归；车市进入强者恒强、价格战收尾阶段。\n 历史 ｜ 2013 年金价暴跌引发\"中国大妈\"抢金，\n 随后套牢数年。\n 影响 ｜ 别把\"抢金饰\"当抄底，金饰有工费\n 溢价；车要看渗透率和出口，别看单月。\n 提示 ｜ 北美已进冬令时，明起美股 22:30\n 开盘（北京时间），晚上看盘可别记错时间。\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━━━━\n\n⑬ 1984年11月1日\n 事实 ｜ 邓小平在中央军委座谈会上提出裁减\n 军队员额 100 万，1985 年正式宣布，\n 1987 年完成。\n 逻辑 ｜ （推演）让国防建设为经济建设让路，\n 腾出的财力投向教育与基建，这是改革开放\n 关键的一步\"减法\"。\n 历史 ｜ 同期美苏军备竞赛正酣，中国反向\n 裁军被称为\"单方面和平姿态\"。\n 影响 ｜ 军费占财政比重大幅下降；今天看，\n 大国战略选择往往先做减法再做加法。\n"}, {"id": 2, "date": "2026-11-02", "title": "每日世界简报 · 2026-11-02", "summary": "美中期选举 · 油价破百 · 可再生能源法修订 · 三季报净利增8.5%", "author": "聪明仔", "items": [{"cat": "国际", "topic": "国际", "t": "美中期选举投票", "s": "民主党押注\"蓝色浪潮\"，两院归属见分晓", "b": "事实：11/2 央视报道，美国中期选举进入最后冲刺，11/3投票改选国会两院；多项民调显示民主党有望掀起\"蓝色浪潮\"。逻辑：（推演）油价破百、物价反复是执政党的软肋，中期选举历来是给总统打分的考试，选民更看钱包不看外交。历史：2018 年中期选举民主党夺回众议院、形成\"分裂国会\"；1994 年共和党 40 年来首次拿下两院。影响：若国会分裂，财政与关税更难落地，全球风险资产波动加大；对 A 股多为情绪扰动，不改趋势。", "src": "央视新闻"}, {"cat": "国际", "topic": "能源", "t": "霍尔木兹仍未开", "s": "伊朗要美先解制裁，油价站上 100 美元", "b": "事实：11/2 伊朗外交部称，美方解除制裁前霍尔木兹海峡不能重开；当日 WTI 原油跌 4% 报 99.95 美元/桶，布伦特报108.99 美元。逻辑：（推演）这条海峡承担全球约五分之一石油海运，只要\"开不开\"悬着，油价就带着地缘溢价——跌也是高位跌。历史：1980 年代两伊\"油轮战\"、2019 年沙特阿美遇袭，都曾让油价单日跳涨一成以上。影响：国内成品油调价跟涨，物流、化工、机票成本抬升；油气开采受益，航空航运与化纤承压。", "src": "财联社 / 新华社"}, {"cat": "国际", "topic": "国际", "t": "比利时首相辞职", "s": "预算谈崩，德韦弗向国王递辞呈", "b": "事实：11/2 比利时媒体报道，因联邦预算谈判未取得突破，首相德韦弗赴王宫向国王菲利普递交辞呈。逻辑：（推演）多党联合政府的共同账本就是预算，削赤字谈不拢，联盟就失去了存在的理由。历史：2010—2011 年比利时曾 541 天组不出政府，创下现代国家\"无政府\"时长纪录。影响：欧元区多一个财政不确定源，欧元短线承压；对国内影响间接，主要经汇率与风险偏好传导。", "src": "新华社 / 华尔街见闻"}, {"cat": "国内·政策", "topic": "能源", "t": "可再生能源法修订", "s": "修订草案初次审议，十章七十六条", "b": "事实：11/2 修订草案提请十四届全国人大常委会第二十五次会议初次审议，共十章七十六条，重点改市场交易与价格机制、消纳责任。逻辑：（推演）把\"发得出、送得走、用得上\"写进法律，等于给绿电的电网接入和消纳上了硬约束。历史：现行法 2005 年通过、2006 年施行，2009 年修正；此后光伏风电从补贴驱动走向平价。影响：绿电、储能、电网改造的中长期订单更确定；居民侧短期无感，工商业电价结构会慢慢变。", "src": "新华社"}, {"cat": "国内·民生", "topic": "医疗", "t": "残疾预防新五年计划", "s": "18 项指标，盯\"一老一小\"和职业病", "b": "事实：《国家残疾预防行动计划（2026—2030年）》发布，设 18项指标、六大行动 19 项举措，聚焦儿童与老人、职业病、慢性病。逻辑：（推演）全国约 4.5 亿慢性病患者，预防比康复便宜得多，防线前移到筛查、适老化改造与职业防护。历史：上一轮为 2021—2025 年行动计划；\"十四五\"新发职业病较\"十三五\"下降 49%。影响：老人防跌倒改造、儿童安全座椅标准会逐步落地；康复与适老化改造行业有增量需求。", "src": "新华社"}, {"cat": "国内·民生", "topic": "就业", "t": "2027 国考报名确认", "s": "未按期确认缴费视为放弃", "b": "事实：央视 11/2 报道，2027 年度国考进入报名确认阶段，考生须按公告时间完成确认与缴费。逻辑：（推演）报名确认是筛掉\"犹豫的人\"的一关，也是各地考位与考场安排的起点。历史：国考报名与确认缴费分离多年，每年都有人因忘记确认而失去考试资格。影响：备考的这两天务必登录确认；热门考点城市先满，跨市赶考的住宿成本就上来了。", "src": "央视新闻"}, {"cat": "国内·生活", "topic": "民生", "t": "浦东能办虹桥值机", "s": "7 家航司国内航班，跨场中转少跑一趟", "b": "事实：11/2 起，虹桥机场值机柜台设在浦东机场 T2 国内到达 C区，可办国航、深航等 7 家航司国内航班，5—20 时开放。逻辑：（推演）机场联络线把两场压到 40 分钟，\"落地浦东、虹桥续飞\"从跑腿变成一次值机。历史：2024 年底机场联络线开通后，东航先试\"空港通\"一次值机；这次直接把柜台搬进对方航站楼。影响：在上海中转省一次取行李再托运；反向柜台 12 月启用，双向打通。", "src": "澎湃新闻"}, {"cat": "国内·生活", "topic": "科技", "t": "AI 魔改视频治理", "s": "10 月清理 1.1 万余条、处置 30 多个号", "b": "事实：广电总局 11/2 披露，重点网络视听平台 10 月\"AI 魔改\"专项治理共清理违规视频 11000 余条、处置违规账号 30余个。逻辑：（推演）AI 把剪辑成本打到近零，侵权门槛也降到近零，平台只能\"发现—下架—封号\"追着跑。历史：2025 年 9 月，《人工智能生成合成内容标识办法》施行，要求 AI 生成内容加标识。影响：刷到的\"经典名场面\"可能随时消失；做二创要留心授权，商用改编风险最高。", "src": "国家广电总局 / 财联社"}, {"cat": "科技", "topic": "科技", "t": "\"九章四号\"获奖", "s": "光量子原型机等 20 项获领先科技奖", "b": "事实：澎湃 11/2 报道，\"九章四号\"光量子计算原型机等 20 项成果获 2026 年世界互联网大会领先科技奖。逻辑：（推演）光量子路线比的是特定问题上的超越，离通用计算还远，但量子优越性在被一次次刷新。历史：2020 年\"九章\"首证量子优越性，2021 年\"九章二号\"、2023 年\"九章三号\"逐级提升。影响：短期不改变手机电脑，长期影响密码、材料模拟、药物设计；相关概念股易被消息驱动。", "src": "澎湃新闻"}, {"cat": "科技", "topic": "能源", "t": "氢能密封件国产线", "s": "淄博试车，电解槽订单近万片", "b": "事实：央视 11/2 报道，国内首条氢能密封材料智能化生产线在山东淄博桓台试车，第 3 代氢能密封垫片已接国内外电解槽订单近万片。逻辑：（推演）氢能常卡在\"小零件\"：密封件漏一点，整套电解槽就白干，国产化从耗材切入最实际。历史：2022 年《氢能产业发展中长期规划》出台，此后电解槽与储运环节国产替代加速。影响：电解槽成本下行，绿氢项目经济性改善；氢能车与绿氢化工降价才有空间。", "src": "央视新闻"}, {"cat": "财经", "topic": "股票", "t": "央行再启互换便利", "s": "11/3 操作，31 家申报超 1000 亿", "b": "事实：央行 11/2 公告，11/3 开展证券、基金、保险公司互换便利（SFISF）操作，期限 1 年可展期；31 家机构申报，额度超 1000 亿元。逻辑：（推演）这是让机构\"以券换流动性\"的工具，不直接撒钱，但能缓解券商基金的资金面紧张。历史：2024 年 10 月创设并首次操作，2025 年 1 月第二次，两次累计 1050 亿元。影响：对股市是\"托底不抬轿\"的温和利好；普通人的感受在基金净值与两融情绪，不在存款利率。", "src": "中国人民银行 / 财联社"}, {"cat": "财经", "topic": "股票", "t": "上市公司三季报收官", "s": "营收 56.8 万亿增 5.9%，净利增 8.5%", "b": "事实：中上协 11/2 数据，全市场 5578 家公司三季报披露完毕：营收 56.8 万亿元、同比增 5.9%，归母净利 5.1 万亿元、增 8.5%，4079 家实现盈利。逻辑：（推演）利润增速快于营收，说明降本增效在起作用；但\"超三成营收净利双增\"意味着分化依旧严重。历史：历年 11 月起的行情多围绕三季报兑现展开，业绩是机构调仓最硬的锚。影响：先看持仓在 5578 家里的位置；净利增速 8.5% 是条及格线，明显低于它的别硬扛。", "src": "中国上市公司协会"}, {"cat": "涨知识", "topic": "能源", "t": "绿电开始按小时算", "s": "宁夏首笔小时级结算，3900 万千瓦时", "b": "事实：央视 11/2 报道，宁夏完成首笔省内小时级绿电交易电费结算：青铜峡铝业与吴忠六十二光伏电站成交 3900 万千瓦时，绿电从\"按月\"变\"按小时\"。逻辑：（推演）光伏中午发、晚上停，按月平均就把\"什么时候的电\"抹平了；按小时算才逼得出储能和灵活负荷。历史：2021 年 9 月全国绿电交易试点启动，最初只有月度、年度合约。影响：高耗能企业买绿电要挑时段，储能与虚拟电厂有了真金白银的价差；居民电价暂不受影响。", "src": "央视新闻"}], "text": "《每日世界简报》 2026-11-02（周一）\n\n① 美中期选举投票    民主党押注\"蓝色浪潮\"，两院归属见分晓\n② 霍尔木兹仍未开    伊朗要美先解制裁，油价站上 100 美元\n③ 比利时首相辞职    预算谈崩，德韦弗向国王递辞呈\n④ 可再生能源法修订    修订草案初次审议，十章七十六条\n⑤ 残疾预防新五年计划    18 项指标，盯\"一老一小\"和职业病\n⑥ 2027 国考报名确认    未按期确认缴费视为放弃\n⑦ 浦东能办虹桥值机    7 家航司国内航班，跨场中转少跑一趟\n⑧ AI 魔改视频治理    10 月清理 1.1 万余条、处置 30 多个号\n⑨ \"九章四号\"获奖    光量子原型机等 20 项获领先科技奖\n⑩ 氢能密封件国产线    淄博试车，电解槽订单近万片\n⑪ 央行再启互换便利    11/3 操作，31 家申报超 1000 亿\n⑫ 上市公司三季报收官    营收 56.8 万亿增 5.9%，净利增 8.5%\n⑬ 绿电开始按小时算    宁夏首笔小时级结算，3900 万千瓦时\n\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━\n\n① 美中期选举投票\n 事实 ｜ 11/2 央视报道，美国中期选举进入最后冲刺，11/3\n     投票改选国会两院；多项民调显示民主党有望掀起\"蓝\n     色浪潮\"。\n 逻辑 ｜ （推演）油价破百、物价反复是执政党的软肋，中期选举\n     历来是给总统打分的考试，选民更看钱包不看外交。\n 历史 ｜ 2018 年中期选举民主党夺回众议院、形成\"分裂国会\"；\n     1994 年共和党 40 年来首次拿下两院。\n 影响 ｜ 若国会分裂，财政与关税更难落地，全球风险资产波动加\n     大；对 A 股多为情绪扰动，不改趋势。\n\n② 霍尔木兹仍未开\n 事实 ｜ 11/2 伊朗外交部称，美方解除制裁前霍尔木兹海峡不能重\n     开；当日 WTI 原油跌 4% 报 99.95 美元/桶，布伦特报\n     108.99 美元。\n 逻辑 ｜ （推演）这条海峡承担全球约五分之一石油海运，只要\"开\n     不开\"悬着，油价就带着地缘溢价——跌也是高位跌。\n 历史 ｜ 1980 年代两伊\"油轮战\"、2019 年沙特阿美遇袭，都曾让\n     油价单日跳涨一成以上。\n 影响 ｜ 国内成品油调价跟涨，物流、化工、机票成本抬升；油气开\n     采受益，航空航运与化纤承压。\n\n③ 比利时首相辞职\n 事实 ｜ 11/2 比利时媒体报道，因联邦预算谈判未取得突破，首相德\n     韦弗赴王宫向国王菲利普递交辞呈。\n 逻辑 ｜ （推演）多党联合政府的共同账本就是预算，削赤字谈不拢，\n     联盟就失去了存在的理由。\n 历史 ｜ 2010—2011 年比利时曾 541 天组不出政府，创下现代国家\n     \"无政府\"时长纪录。\n 影响 ｜ 欧元区多一个财政不确定源，欧元短线承压；对国内影响间\n     接，主要经汇率与风险偏好传导。\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━━━━━━━━━━━\n\n④ 可再生能源法修订\n 事实 ｜ 11/2 修订草案提请十四届全国人大常委会第二十五次会议初\n     次审议，共十章七十六条，重点改市场交易与价格机制、\n     消纳责任。\n 逻辑 ｜ （推演）把\"发得出、送得走、用得上\"写进法律，等于给绿\n     电的电网接入和消纳上了硬约束。\n 历史 ｜ 现行法 2005 年通过、2006 年施行，2009 年修正；此后光\n     伏风电从补贴驱动走向平价。\n 影响 ｜ 绿电、储能、电网改造的中长期订单更确定；居民侧短期无\n     感，工商业电价结构会慢慢变。\n\n⑤ 残疾预防新五年计划\n 事实 ｜ 《国家残疾预防行动计划（2026—2030年）》发布，设 18\n     项指标、六大行动 19 项举措，聚焦儿童与老人、职业病、\n     慢性病。\n 逻辑 ｜ （推演）全国约 4.5 亿慢性病患者，预防比康复便宜得多，\n     防线前移到筛查、适老化改造与职业防护。\n 历史 ｜ 上一轮为 2021—2025 年行动计划；\"十四五\"新发职业病较\n     \"十三五\"下降 49%。\n 影响 ｜ 老人防跌倒改造、儿童安全座椅标准会逐步落地；康复与适\n     老化改造行业有增量需求。\n\n⑥ 2027 国考报名确认\n 事实 ｜ 央视 11/2 报道，2027 年度国考进入报名确认阶段，考生须\n     按公告时间完成确认与缴费。\n 逻辑 ｜ （推演）报名确认是筛掉\"犹豫的人\"的一关，也是各地考位\n     与考场安排的起点。\n 历史 ｜ 国考报名与确认缴费分离多年，每年都有人因忘记确认而失\n     去考试资格。\n 影响 ｜ 备考的这两天务必登录确认；热门考点城市先满，跨市赶考\n     的住宿成本就上来了。\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━━━━━━━\n\n⑦ 浦东能办虹桥值机\n 事实 ｜ 11/2 起，虹桥机场值机柜台设在浦东机场 T2 国内到达 C\n     区，可办国航、深航等 7 家航司国内航班，5—20 时开放。\n 逻辑 ｜ （推演）机场联络线把两场压到 40 分钟，\"落地浦东、虹桥\n     续飞\"从跑腿变成一次值机。\n 历史 ｜ 2024 年底机场联络线开通后，东航先试\"空港通\"一次值机；\n     这次直接把柜台搬进对方航站楼。\n 影响 ｜ 在上海中转省一次取行李再托运；反向柜台 12 月启用，双\n     向打通。\n\n⑧ AI 魔改视频治理\n 事实 ｜ 广电总局 11/2 披露，重点网络视听平台 10 月\"AI 魔改\"\n     专项治理共清理违规视频 11000 余条、处置违规账号 30\n     余个。\n 逻辑 ｜ （推演）AI 把剪辑成本打到近零，侵权门槛也降到近零，平\n     台只能\"发现—下架—封号\"追着跑。\n 历史 ｜ 2025 年 9 月，《人工智能生成合成内容标识办法》施行，\n     要求 AI 生成内容加标识。\n 影响 ｜ 刷到的\"经典名场面\"可能随时消失；做二创要留心授权，商\n     用改编风险最高。\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━━━━━━━\n\n⑨ \"九章四号\"获奖\n 事实 ｜ 澎湃 11/2 报道，\"九章四号\"光量子计算原型机等 20 项成\n     果获 2026 年世界互联网大会领先科技奖。\n 逻辑 ｜ （推演）光量子路线比的是特定问题上的超越，离通用计算还\n     远，但量子优越性在被一次次刷新。\n 历史 ｜ 2020 年\"九章\"首证量子优越性，2021 年\"九章二号\"、\n     2023 年\"九章三号\"逐级提升。\n 影响 ｜ 短期不改变手机电脑，长期影响密码、材料模拟、药物设计；\n     相关概念股易被消息驱动。\n\n⑩ 氢能密封件国产线\n 事实 ｜ 央视 11/2 报道，国内首条氢能密封材料智能化生产线在山东\n     淄博桓台试车，第 3 代氢能密封垫片已接国内外电解槽订\n     单近万片。\n 逻辑 ｜ （推演）氢能常卡在\"小零件\"：密封件漏一点，整套电解槽\n     就白干，国产化从耗材切入最实际。\n 历史 ｜ 2022 年《氢能产业发展中长期规划》出台，此后电解槽与储\n     运环节国产替代加速。\n 影响 ｜ 电解槽成本下行，绿氢项目经济性改善；氢能车与绿氢化工\n     降价才有空间。\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━━━━━━━━━━━\n\n⑪ 央行再启互换便利\n 事实 ｜ 央行 11/2 公告，11/3 开展证券、基金、保险公司互换便利\n     （SFISF）操作，期限 1 年可展期；31 家机构申报，额\n     度超 1000 亿元。\n 逻辑 ｜ （推演）这是让机构\"以券换流动性\"的工具，不直接撒钱，\n     但能缓解券商基金的资金面紧张。\n 历史 ｜ 2024 年 10 月创设并首次操作，2025 年 1 月第二次，两次\n     累计 1050 亿元。\n 影响 ｜ 对股市是\"托底不抬轿\"的温和利好；普通人的感受在基金净\n     值与两融情绪，不在存款利率。\n\n⑫ 上市公司三季报收官\n 事实 ｜ 中上协 11/2 数据，全市场 5578 家公司三季报披露完毕：\n     营收 56.8 万亿元、同比增 5.9%，归母净利 5.1 万亿元、\n     增 8.5%，4079 家实现盈利。\n 逻辑 ｜ （推演）利润增速快于营收，说明降本增效在起作用；但\"超\n     三成营收净利双增\"意味着分化依旧严重。\n 历史 ｜ 历年 11 月起的行情多围绕三季报兑现展开，业绩是机构调仓\n     最硬的锚。\n 影响 ｜ 先看持仓在 5578 家里的位置；净利增速 8.5% 是条及格线，\n     明显低于它的别硬扛。\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━━━━━━━━━\n\n⑬ 绿电开始按小时算\n 事实 ｜ 央视 11/2 报道，宁夏完成首笔省内小时级绿电交易电费结\n     算：青铜峡铝业与吴忠六十二光伏电站成交 3900 万千瓦\n     时，绿电从\"按月\"变\"按小时\"。\n 逻辑 ｜ （推演）光伏中午发、晚上停，按月平均就把\"什么时候的\n     电\"抹平了；按小时算才逼得出储能和灵活负荷。\n 历史 ｜ 2021 年 9 月全国绿电交易试点启动，最初只有月度、年度\n     合约。\n 影响 ｜ 高耗能企业买绿电要挑时段，储能与虚拟电厂有了真金白银\n     的价差；居民电价暂不受影响。\n"}, {"id": 3, "date": "2026-11-03", "title": "每日世界简报 · 2026-11-03", "summary": "中期选举·霍尔木兹·外汇存准率·央行购金·存储涨价", "author": "聪明仔", "items": [{"cat": "国际", "topic": "国际", "t": "美国中期选举投票开启", "s": "众议院435席全部改选、参议院35席，特朗普第二任期的期中考试", "b": "事实：美东时间3日6时（北京时间19时）起，缅因、纽约、弗吉尼亚等州投票点开放。众议院435席全部改选，参议院100席中35席改选，另选36个州长。（新华社）\n逻辑：（推演）通胀与生活成本是核心议题，胜负看投票率与郊区女性选民；若国会分裂，财政与关税推进更难。\n历史：2018年中期选举共和党丢众议院40席；2022年“红潮”未现。中期选举历来被当作对在任总统的公投。\n影响：结果牵动美元、美债与关税节奏，对A股是外溢变量，出口链与科技管制口径最敏感。", "src": "新华社"}, {"cat": "国际", "topic": "国际", "t": "霍尔木兹三艘油轮起火", "s": "伊方称油轮触雷爆炸搁浅，同时击落两架美军无人机", "b": "事实：伊朗革命卫队海军3日称，三艘油轮自凌晨起在霍尔木兹海峡“非法航道”触雷爆炸后搁浅南岸；同日伊方称击落两架美军无人机，并在格什姆岛以南俘获2架MQM-170侦察机。（央视、IRIB）\n逻辑：（推演）双方都在“打但不打大”，用可控摩擦攒谈判筹码；布雷与无人机是低成本、高传播的手段。\n历史：2019年6月阿曼湾两艘油轮遇袭、同年沙特阿美Abqaiq遇袭，油价单日跳涨约15%，两周后回吐。\n影响：霍尔木兹承担全球约五分之一海运原油，封锁预期一升，油价与航运保费就涨，国内成品油调价、化工成本跟着波动。", "src": "央视新闻、IRIB"}, {"cat": "国际", "topic": "国际", "t": "卡塔尔斡旋给36小时窗口", "s": "美伊将就新提案反馈，油价回落，布伦特跌破105美元", "b": "事实：卡塔尔外交部3日称，斡旋团队2日晚访德黑兰后返多哈，谈判继续，美伊将在36小时内对新提案反馈。伊朗总统称最高领袖已授权就“不可谈判”议题对话。布伦特跌破105美元/桶报104.99，WTI一度跌破97。（央视、华尔街见闻）\n逻辑：（推演）“授权对话”是给国内强硬派的台阶，“36小时”是给市场的时间锚；油价回落说明市场在押注谈成。\n历史：2015年伊核协议谈成前也反复出现“最后窗口”；2018年美国退出后制裁重启，伊朗原油出口从约250万桶/日降至不足50万桶/日。\n影响：谈成则油价与航运成本回落；谈崩则油价冲高，国内92号汽油与化工品价格跟涨。", "src": "央视新闻、华尔街见闻"}, {"cat": "国内·政策", "topic": "政策", "t": "央行上调外汇存款准备金率", "s": "近5年首次上调，现行4%，意在压住单边升值预期", "b": "事实：11月3日央行上调金融机构外汇存款准备金率，现行水平为4%（2022年至2023年三次下调至此，具体新档位以官方公告为准）。民生银行温彬称这是公开透明的市场化措施，连平称目的是避免单边快速升值预期。（央视、华尔街见闻）\n逻辑：（推演）人民币偏强、外汇供给充裕时上调，等于收紧境内美元流动性、抬高做多人民币成本，属逆周期加宏观审慎，不是货币紧缩。\n历史：2021年央行两次上调该率至9%压升值；2022年至2023年三次下调至4%对冲贬值。这个工具一直升贬两用。\n影响：出口企业结汇节奏要变，换汇成本略升；普通人不必抢在一天内换汇，人民币单边快升概率下降。", "src": "央视新闻、华尔街见闻"}, {"cat": "国内·政策", "topic": "政策", "t": "人大常委会审议多部法律", "s": "检察公益诉讼法、水法、可再生能源法修订同期推进", "b": "事实：十四届全国人大常委会第二十五次会议在京举行，审议检察公益诉讼法草案、水法修订草案等；可再生能源法修订草案已提请审议。同日《国家残疾预防行动计划（2026—2030年）》发布。（新华社、澎湃新闻）\n逻辑：（推演）公益诉讼立法是把“检察院替公众打官司”从实践变制度；水法与可再生能源法同修，指向水资源刚性约束与绿电消纳。\n历史：2017年检察公益诉讼正式入法，此后案件量从每年几千件增至十万件级。\n影响：环境、食药、个人信息领域的公益索赔会更常见；绿电与水电价格机制调整会传导到居民电价结构。", "src": "新华社、澎湃新闻"}, {"cat": "国内·政策", "topic": "就业", "t": "发改委推介50个民企项目", "s": "农业、制造业等领域公开推介，专利审查十五五规划同日印发", "b": "事实：国家发改委民营局围绕农业、制造业等领域，向民营企业公开推介50个投资项目；同日国家知识产权局印发《专利和商标审查“十五五”规划》。（华尔街见闻）\n逻辑：（推演）民间投资偏弱时，给项目清单比喊口号有效；能否落地要看融资成本与回报机制。\n历史：2023年起发改委多次推介民间资本项目（含核电、铁路），部分落地率不高，卡点在收益率与准入。\n影响：对民企是订单与准入信号，对就业是制造业岗位的边际改善，但短期见不到效果。", "src": "华尔街见闻"}, {"cat": "国内·生活", "topic": "天气", "t": "最强厄尔尼诺影响今冬明春", "s": "气象局称有记录以来最强，同江段已提前进入流冰期", "b": "事实：中国气象局11月3日发布会称，有监测记录以来最强厄尔尼诺事件将对我国今冬明春气候产生明显影响；黑龙江、松花江同江段已提前进入流冰期。（华尔街见闻、央视新闻）\n逻辑：（推演）厄尔尼诺年冬季常偏暖、南涝北旱。暖冬压低取暖需求、抬高病虫害越冬基数，但也会有阶段性强降温。\n历史：2015至2016年超强厄尔尼诺，2016年长江流域汛期严重洪涝；1997至1998年厄尔尼诺叠加，致1998年大洪水。\n影响：菜价与农产品期货先反应，暖冬利空煤炭与取暖电器，利好春耕前墒情。", "src": "华尔街见闻、央视新闻"}, {"cat": "国内·生活", "topic": "就业", "t": "广东落实带薪年休假", "s": "地方层面硬推休假，与“促消费”直接挂钩", "b": "事实：广东提出全面落实带薪年休假制度（百度热搜，具体文件表述以官方发布为准）。（百度热搜）\n逻辑：（推演）假期是消费的时间前提，落实年休假等于给服务消费“发放时间”，也缓解集中黄金周的压力。\n历史：2015年以来多次发文落实带薪休假，实际执行率长期偏低，民企与制造业尤甚。\n影响：若真落地，员工可拼假错峰出游，机票酒店更便宜；但企业用工成本上升，部分岗位可能改为弹性排班。", "src": "百度热搜"}, {"cat": "科技", "topic": "科技", "t": "乌镇峰会：全球网民约63亿", "s": "国际电信联盟数据，增量见顶，竞争转向抢时长", "b": "事实：2026年世界互联网大会乌镇峰会在浙江举行，国际电信联盟称2026年全球网民约63亿；张朝阳称搜狐视频重启美剧战略；智元获大会杰出贡献奖。（华尔街见闻、新浪财经）\n逻辑：（推演）网民数接近人口天花板，增量红利结束，平台从拉新转向抢使用时长，这也是争抢优质内容的底层原因。\n历史：2015年全球网民约32亿，十年翻倍；中国网民已近11亿，增速降到1%附近。\n影响：内容付费与广告单价的博弈更激烈，用户面对的是会员涨价与广告变多。", "src": "华尔街见闻、新浪财经"}, {"cat": "科技", "topic": "科技", "t": "无锡2000卡国产智算满载", "s": "摩尔线程MTT S5000利用率超92%，2027年目标10万卡", "b": "事实：无锡（惠山）国产智算中心2000张摩尔线程MTT S5000接近满载，92%以上算力已在使用，从6月点亮到满载只用两个多月；摩尔线程副总裁称2027年建10万卡集群是重要战略。（新浪财经）\n逻辑：（推演）国产卡的瓶颈从“能不能跑”转向利用率与生态，满载率比参数更硬；10万卡目标考验电力与液冷配套。\n历史：2023年起国内智算中心被批“建而不用”，多地算力利用率不足30%，这次92%是少见的正面样本。\n影响：影响算力租赁价格与国产GPU供应链订单；间接决定AI服务价格能不能降下来。", "src": "新浪财经"}, {"cat": "财经", "topic": "黄金", "t": "全球央行购金创年内新高", "s": "金饰需求却跌到历史同期最低，官方托底民间观望", "b": "事实：三季度全球央行购金量创年内新高，金饰需求跌至历史同期最低（澎湃新闻）；印度2026年前三季度黄金进口162.5吨，同比降29%，其中投资需求降40%。（澎湃新闻、新华社）\n逻辑：（推演）央行买金是储备多元化、对价格不敏感；金饰需求对价格高度敏感。两者背离说明高价正在挤出民间消费。\n历史：2022至2024年央行连续三年购金超1000吨，创1950年代以来纪录；2011年金价见顶后金饰需求同样萎缩，随后金价横盘三年。\n影响：金饰零售买卖价差扩大，追高买饰品的最容易亏；想配黄金优先金条或ETF，别为工艺溢价买单。", "src": "澎湃新闻、新华社"}, {"cat": "财经", "topic": "债券", "t": "惠誉上调四家中资银行评级", "s": "民生升至BBB，广发、平安、华夏升至BBB-，展望稳定", "b": "事实：11月3日惠誉将民生银行长期外币发行人主体评级由BBB-上调至BBB，将广发、平安、华夏由BB+上调至BBB-，展望均为稳定。（上证报、华尔街见闻）\n逻辑：（推演）评级上调直接降低境外发债成本，也是对资产质量与资本补充的背书；但股份行零售不良与息差压力仍在。\n历史：2023年惠誉下调多家美国银行评级曾引发全球银行股调整，评级行动对跨境融资成本影响很直接。\n影响：相关银行美元债与优先股受益；储户无直接影响，但含这些银行资本工具的理财估值会小幅改善。", "src": "上证报、华尔街见闻"}, {"cat": "财经", "topic": "科技", "t": "DDR缺货涨价30%，夜盘商品普跌", "s": "存储短缺传导到消费电子，焦煤沪银原油夜盘齐跌", "b": "事实：协创数据称DDR非常短缺，最近报价已提高30%且被接受；夜盘国内期货焦煤、沪锡、沪银跌近2%，低硫燃料油、SC原油、燃料油跌超1%，烧碱、塑料涨超1%。（华尔街见闻）\n逻辑：（推演）AI训练与服务器需求挤占存储产能，涨价从HBM传导到DDR和消费电子；商品普跌则在定价全球需求走弱与地缘缓和。\n历史：2017至2018年存储涨价周期持续约8个季度，随后产能释放价格腰斩；2021年缺芯同样先涨后崩。\n影响：手机、笔记本、固态硬盘明年可能涨价，想换机的可提前；做期货的别追单边。", "src": "华尔街见闻"}, {"cat": "涨知识", "topic": "历史", "t": "为什么不申办2036年奥运会", "s": "奥运经济账变了：场馆成本高企，收入大头归国际奥委会", "b": "事实：网络热议“中国不申办2036年奥运会”（百度热搜，官方正式表述待确认）。（百度热搜）\n逻辑：（推演）主办城市主要得旅游与基建，转播与顶级赞助收入归国际奥委会，成本却全留本地，边际收益递减。\n历史：1976年蒙特利尔奥运亏损约15亿美元、债务还了30年；2004年雅典亏损约80亿欧元；2020东京空场办赛亏损超100亿美元。\n影响：不申办意味着财政少一笔大开支，钱更可能流向民生与产业；对体育迷是少了主场观赛机会。", "src": "百度热搜"}], "text": "《每日世界简报》 2026-11-03（周二）\n\n① 美国中期选举投票开启    众议院435席全部改选、参议院35席，特朗普第二任期的期中考试\n② 霍尔木兹三艘油轮起火    伊方称油轮触雷爆炸搁浅，同时击落两架美军无人机\n③ 卡塔尔斡旋给36小时窗口    美伊将就新提案反馈，油价回落，布伦特跌破105美元\n④ 央行上调外汇存款准备金率    近5年首次上调，现行4%，意在压住单边升值预期\n⑤ 人大常委会审议多部法律    检察公益诉讼法、水法、可再生能源法修订同期推进\n⑥ 发改委推介50个民企项目    农业、制造业等领域公开推介，专利审查十五五规划同日印发\n⑦ 最强厄尔尼诺影响今冬明春    气象局称有记录以来最强，同江段已提前进入流冰期\n⑧ 广东落实带薪年休假    地方层面硬推休假，与“促消费”直接挂钩\n⑨ 乌镇峰会：全球网民约63亿    国际电信联盟数据，增量见顶，竞争转向抢时长\n⑩ 无锡2000卡国产智算满载    摩尔线程MTT S5000利用率超92%，2027年目标10万卡\n⑪ 全球央行购金创年内新高    金饰需求却跌到历史同期最低，官方托底民间观望\n⑫ 惠誉上调四家中资银行评级    民生升至BBB，广发、平安、华夏升至BBB-，展望稳定\n⑬ DDR缺货涨价30%，夜盘商品普跌    存储短缺传导到消费电子，焦煤沪银原油夜盘齐跌\n⑭ 为什么不申办2036年奥运会    奥运经济账变了：场馆成本高企，收入大头归国际奥委会\n\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━\n\n① 美国中期选举投票开启\n 事实 ｜ 美东时间3日6时（北京时间19时）起，缅因、纽约、弗\n     吉尼亚等州投票点开放。众议院435席全部改选，参议\n     院100席中35席改选，另选36个州长。（新华社）\n 逻辑 ｜ （推演）通胀与生活成本是核心议题，胜负看投票率与\n     郊区女性选民；若国会分裂，财政与关税推进更难。\n 历史 ｜ 2018年中期选举共和党丢众议院40席；2022年“红潮”\n     未现。中期选举历来被当作对在任总统的公投。\n 影响 ｜ 结果牵动美元、美债与关税节奏，对A股是外溢变量，\n     出口链与科技管制口径最敏感。\n\n② 霍尔木兹三艘油轮起火\n 事实 ｜ 伊朗革命卫队海军3日称，三艘油轮自凌晨起在霍尔木\n     兹海峡“非法航道”触雷爆炸后搁浅南岸；同日伊方称\n     击落两架美军无人机，并在格什姆岛以南俘获2架\n     MQM-170侦察机。（央视、IRIB）\n 逻辑 ｜ （推演）双方都在“打但不打大”，用可控摩擦攒谈判\n     筹码；布雷与无人机是低成本、高传播的手段。\n 历史 ｜ 2019年6月阿曼湾两艘油轮遇袭、同年沙特阿美Abqaiq\n     遇袭，油价单日跳涨约15%，两周后回吐。\n 影响 ｜ 霍尔木兹承担全球约五分之一海运原油，封锁预期一升，\n     油价与航运保费就涨，国内成品油调价、化工成本跟着\n     波动。\n\n③ 卡塔尔斡旋给36小时窗口\n 事实 ｜ 卡塔尔外交部3日称，斡旋团队2日晚访德黑兰后返多哈，\n     谈判继续，美伊将在36小时内对新提案反馈。伊朗总统\n     称最高领袖已授权就“不可谈判”议题对话。布伦特跌\n     破105美元/桶报104.99，WTI一度跌破97。（央视、华\n     尔街见闻）\n 逻辑 ｜ （推演）“授权对话”是给国内强硬派的台阶，“36小\n     时”是给市场的时间锚；油价回落说明市场在押注谈成。\n 历史 ｜ 2015年伊核协议谈成前也反复出现“最后窗口”；2018\n     年美国退出后制裁重启，伊朗原油出口从约250万桶/日\n     降至不足50万桶/日。\n 影响 ｜ 谈成则油价与航运成本回落；谈崩则油价冲高，国内92\n     号汽油与化工品价格跟涨。\n\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━\n\n④ 央行上调外汇存款准备金率\n 事实 ｜ 11月3日央行上调金融机构外汇存款准备金率，现行水\n     平为4%（2022年至2023年三次下调至此，具体新档位以\n     官方公告为准）。民生银行温彬称这是公开透明的市场\n     化措施，连平称目的是避免单边快速升值预期。（央视、\n     华尔街见闻）\n 逻辑 ｜ （推演）人民币偏强、外汇供给充裕时上调，等于收紧\n     境内美元流动性、抬高做多人民币成本，属逆周期加宏\n     观审慎，不是货币紧缩。\n 历史 ｜ 2021年央行两次上调该率至9%压升值；2022年至2023年\n     三次下调至4%对冲贬值。这个工具一直升贬两用。\n 影响 ｜ 出口企业结汇节奏要变，换汇成本略升；普通人不必抢\n     在一天内换汇，人民币单边快升概率下降。\n\n⑤ 人大常委会审议多部法律\n 事实 ｜ 十四届全国人大常委会第二十五次会议在京举行，审议\n     检察公益诉讼法草案、水法修订草案等；可再生能源法\n     修订草案已提请审议。同日《国家残疾预防行动计划（\n     2026—2030年）》发布。（新华社、澎湃新闻）\n 逻辑 ｜ （推演）公益诉讼立法是把“检察院替公众打官司”从\n     实践变制度；水法与可再生能源法同修，指向水资源刚\n     性约束与绿电消纳。\n 历史 ｜ 2017年检察公益诉讼正式入法，此后案件量从每年几千\n     件增至十万件级。\n 影响 ｜ 环境、食药、个人信息领域的公益索赔会更常见；绿电\n     与水电价格机制调整会传导到居民电价结构。\n\n⑥ 发改委推介50个民企项目\n 事实 ｜ 国家发改委民营局围绕农业、制造业等领域，向民营企\n     业公开推介50个投资项目；同日国家知识产权局印发《\n     专利和商标审查“十五五”规划》。（华尔街见闻）\n 逻辑 ｜ （推演）民间投资偏弱时，给项目清单比喊口号有效；\n     能否落地要看融资成本与回报机制。\n 历史 ｜ 2023年起发改委多次推介民间资本项目（含核电、铁路），\n     部分落地率不高，卡点在收益率与准入。\n 影响 ｜ 对民企是订单与准入信号，对就业是制造业岗位的边际\n     改善，但短期见不到效果。\n\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━\n\n⑦ 最强厄尔尼诺影响今冬明春\n 事实 ｜ 中国气象局11月3日发布会称，有监测记录以来最强厄\n     尔尼诺事件将对我国今冬明春气候产生明显影响；黑龙\n     江、松花江同江段已提前进入流冰期。（华尔街见闻、\n     央视新闻）\n 逻辑 ｜ （推演）厄尔尼诺年冬季常偏暖、南涝北旱。暖冬压低\n     取暖需求、抬高病虫害越冬基数，但也会有阶段性强降\n     温。\n 历史 ｜ 2015至2016年超强厄尔尼诺，2016年长江流域汛期严重\n     洪涝；1997至1998年厄尔尼诺叠加，致1998年大洪水。\n 影响 ｜ 菜价与农产品期货先反应，暖冬利空煤炭与取暖电器，\n     利好春耕前墒情。\n\n⑧ 广东落实带薪年休假\n 事实 ｜ 广东提出全面落实带薪年休假制度（百度热搜，具体文\n     件表述以官方发布为准）。（百度热搜）\n 逻辑 ｜ （推演）假期是消费的时间前提，落实年休假等于给服\n     务消费“发放时间”，也缓解集中黄金周的压力。\n 历史 ｜ 2015年以来多次发文落实带薪休假，实际执行率长期偏\n     低，民企与制造业尤甚。\n 影响 ｜ 若真落地，员工可拼假错峰出游，机票酒店更便宜；但\n     企业用工成本上升，部分岗位可能改为弹性排班。\n\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━\n\n⑨ 乌镇峰会：全球网民约63亿\n 事实 ｜ 2026年世界互联网大会乌镇峰会在浙江举行，国际电信\n     联盟称2026年全球网民约63亿；张朝阳称搜狐视频重启\n     美剧战略；智元获大会杰出贡献奖。（华尔街见闻、新\n     浪财经）\n 逻辑 ｜ （推演）网民数接近人口天花板，增量红利结束，平台\n     从拉新转向抢使用时长，这也是争抢优质内容的底层原\n     因。\n 历史 ｜ 2015年全球网民约32亿，十年翻倍；中国网民已近11亿，\n     增速降到1%附近。\n 影响 ｜ 内容付费与广告单价的博弈更激烈，用户面对的是会员\n     涨价与广告变多。\n\n⑩ 无锡2000卡国产智算满载\n 事实 ｜ 无锡（惠山）国产智算中心2000张摩尔线程MTT S5000\n     接近满载，92%以上算力已在使用，从6月点亮到满载只\n     用两个多月；摩尔线程副总裁称2027年建10万卡集群是\n     重要战略。（新浪财经）\n 逻辑 ｜ （推演）国产卡的瓶颈从“能不能跑”转向利用率与生\n     态，满载率比参数更硬；10万卡目标考验电力与液冷配\n     套。\n 历史 ｜ 2023年起国内智算中心被批“建而不用”，多地算力利\n     用率不足30%，这次92%是少见的正面样本。\n 影响 ｜ 影响算力租赁价格与国产GPU供应链订单；间接决定AI\n     服务价格能不能降下来。\n\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━\n\n⑪ 全球央行购金创年内新高\n 事实 ｜ 三季度全球央行购金量创年内新高，金饰需求跌至历史\n     同期最低（澎湃新闻）；印度2026年前三季度黄金进口\n     162.5吨，同比降29%，其中投资需求降40%。（澎湃新\n     闻、新华社）\n 逻辑 ｜ （推演）央行买金是储备多元化、对价格不敏感；金饰\n     需求对价格高度敏感。两者背离说明高价正在挤出民间\n     消费。\n 历史 ｜ 2022至2024年央行连续三年购金超1000吨，创1950年代\n     以来纪录；2011年金价见顶后金饰需求同样萎缩，随后\n     金价横盘三年。\n 影响 ｜ 金饰零售买卖价差扩大，追高买饰品的最容易亏；想配\n     黄金优先金条或ETF，别为工艺溢价买单。\n\n⑫ 惠誉上调四家中资银行评级\n 事实 ｜ 11月3日惠誉将民生银行长期外币发行人主体评级由\n     BBB-上调至BBB，将广发、平安、华夏由BB+上调至BBB-，\n     展望均为稳定。（上证报、华尔街见闻）\n 逻辑 ｜ （推演）评级上调直接降低境外发债成本，也是对资产\n     质量与资本补充的背书；但股份行零售不良与息差压力\n     仍在。\n 历史 ｜ 2023年惠誉下调多家美国银行评级曾引发全球银行股调\n     整，评级行动对跨境融资成本影响很直接。\n 影响 ｜ 相关银行美元债与优先股受益；储户无直接影响，但含\n     这些银行资本工具的理财估值会小幅改善。\n\n⑬ DDR缺货涨价30%，夜盘商品普跌\n 事实 ｜ 协创数据称DDR非常短缺，最近报价已提高30%且被接受；\n     夜盘国内期货焦煤、沪锡、沪银跌近2%，低硫燃料油、\n     SC原油、燃料油跌超1%，烧碱、塑料涨超1%。（华尔街\n     见闻）\n 逻辑 ｜ （推演）AI训练与服务器需求挤占存储产能，涨价从\n     HBM传导到DDR和消费电子；商品普跌则在定价全球需求\n     走弱与地缘缓和。\n 历史 ｜ 2017至2018年存储涨价周期持续约8个季度，随后产能\n     释放价格腰斩；2021年缺芯同样先涨后崩。\n 影响 ｜ 手机、笔记本、固态硬盘明年可能涨价，想换机的可提\n     前；做期货的别追单边。\n\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━\n\n⑭ 为什么不申办2036年奥运会\n 事实 ｜ 网络热议“中国不申办2036年奥运会”（百度热搜，官\n     方正式表述待确认）。（百度热搜）\n 逻辑 ｜ （推演）主办城市主要得旅游与基建，转播与顶级赞助\n     收入归国际奥委会，成本却全留本地，边际收益递减。\n 历史 ｜ 1976年蒙特利尔奥运亏损约15亿美元、债务还了30年；\n     2004年雅典亏损约80亿欧元；2020东京空场办赛亏损超\n     100亿美元。\n 影响 ｜ 不申办意味着财政少一笔大开支，钱更可能流向民生与\n     产业；对体育迷是少了主场观赛机会。\n\n\n想深挖哪条说一声。"}, {"id": 4, "date": "2026-11-04", "title": "每日世界简报 · 2026-11-04", "summary": "美中期选举·欧央行加息·西藏强雨雪·A股大反弹", "author": "聪明仔", "items": [{"cat": "国际", "topic": "国际", "t": "美中期选举落幕", "s": "民主党赢回国会控制权，特朗普承认对手取得优势", "b": "事实：民主党赢得国会控制权，内华达州长由该党福特夺回；特朗普回应称不看作个人失败，因为自己名字不在选票上。\n逻辑：（推演）国会易手后，减税与财政扩张难过关，白宫转入跛脚鸭期，政策更依赖行政令推进。\n历史：2018年中期选举共和党丢掉众议院，此后两年立法基本停摆；1994年克林顿同样失守两院。\n影响：政策不确定性下降，美股期货走高，标普500期货涨约1%；但关税与科技管制走行政程序，不因国会易手而停。", "src": "新浪财经7x24·美联社"}, {"cat": "国际", "topic": "国际", "t": "中东双线升温", "s": "特朗普称对伊朗发动小规模攻击，乌方称扎波罗热空袭致37死", "b": "事实：特朗普称对伊朗发动小规模攻击；乌方称11月2日扎波罗热科米舒瓦斯空袭已致37人死亡，搜救仍在进行。\n逻辑：（推演）美方以有限打击维持威慑又避免全面战争，油价反应克制：布伦特回落至101美元下方，日内跌2.65%。\n历史：2020年1月美军击杀苏莱曼尼后伊朗导弹报复，双方刻意控局，油价两周内回吐全部涨幅。\n影响：原油回落意味着下一轮国内成品油调价压力减轻；若霍尔木兹海峡出事，运费与油价会立刻反弹。", "src": "澎湃新闻·乌克兰紧急服务部门"}, {"cat": "国际", "topic": "国际", "t": "欧元区通胀回4%", "s": "欧元区10月CPI升至4%创三年新高，12月加息预期升温", "b": "事实：欧盟统计局初值显示，欧元区10月CPI同比4.0%，高于9月的3.8%，为2023年9月以来最高，能源涨幅居首；核心CPI 2.5%。\n逻辑：（推演）通胀回到目标两倍，欧央行10月按兵不动被解读为暂停而非结束，市场押注12月加息。\n历史：2022年欧元区通胀曾破10%，欧央行一年内加息450个基点，直到2023年才见顶回落。\n影响：加息预期推高欧元、压低美元，间接利好美元计价的黄金；出口欧洲的企业要防需求走弱。", "src": "央视新闻·华尔街见闻"}, {"cat": "国内·政策", "topic": "政策", "t": "五中全会精神落地", "s": "全国政协常委会闭幕，国办印发AI就业友好型发展方式意见", "b": "事实：全国政协十四届常委会第十九次会议4日下午闭幕，主题是贯彻二十届五中全会精神；国办印发关于适应人工智能技术发展助力构建就业友好型发展方式的意见。\n逻辑：（推演）把AI替代岗位提前纳入政策视野，说明决策层判断冲击已到需要预案的阶段。\n历史：2015年互联网+写入政府工作报告后，配套就业与培训政策跟进约两年；这次节奏明显更快。\n影响：转岗培训、社保衔接类政策可能加速落地；对AI应用企业是合规与补贴并行的通道。", "src": "新华网·金十数据"}, {"cat": "国内·政策", "topic": "政策", "t": "立法与规划密集", "s": "可再生能源法修订草案提请审议，专利商标审查十五五规划印发", "b": "事实：可再生能源法修订草案提请审议；国家知识产权局印发专利和商标审查十五五规划；国家残疾预防行动计划2026—2030年发布。\n逻辑：（推演）新能源从鼓励装机转向入市消纳，法律层面要为绿电交易与储能责任划清边界。\n历史：2005年可再生能源法首立、2009年修正确立全额保障性收购，每次修订都对应一轮装机结构变化。\n影响：光伏风电的电价机制与消纳责任可能再调整，持有新能源电站或相关基金的人要留意细则。", "src": "新华网"}, {"cat": "国内·民生", "topic": "民生", "t": "民生两笔账", "s": "养老消费补贴惠及243万失能老人，十五五末社零约60万亿元", "b": "事实：养老服务消费补贴已惠及243万失能老年人；央视报道十五五末社会消费品零售总额将达约60万亿元。\n逻辑：（推演）补贴直接补给失能老人家庭，等于用财政把照护需求变成可支付的服务消费。\n历史：2020年起多地试点长期护理保险，参保人照护支出自付比例平均降约三成。\n影响：家里有失能老人的可关注本地补贴申领口径；服务消费是下一阶段政策重点。", "src": "新华网·央视新闻"}, {"cat": "国内·生活", "topic": "天气", "t": "西藏强雨雪", "s": "西藏南部有强雨雪，东西两路冷空气明起南下", "b": "事实：中央气象台提示西藏南部等地有强雨雪，明起东西两路冷空气将南下；两部门已部署西藏强降雪天气防范应对。\n逻辑：（推演）高原强降雪叠加震区安置，救灾难度高于平原；两路冷空气夹击会让中东部降温更明显。\n历史：2023年12月甘肃积石山地震后同样遇寒潮，低温一度成为救援最大变量。\n影响：未来三天高原与西北出行要防封路；中东部昼夜温差拉大，心脑血管人群注意保暖。", "src": "新华网·中央气象台"}, {"cat": "国内·生活", "topic": "民生", "t": "小切口便民", "s": "多地机关内部厕所常态化开放，12306上线团体票新功能", "b": "事实：多地机关单位内部厕所常态化对外开放；铁路12306上线新功能，买团体票更方便；国内最长地铁环线全线开通。\n逻辑：（推演）公共资源错时共享成本低、见效快，是城市治理里少见的低争议增量。\n历史：2018年起多地推行机关停车场夜间开放，做法与此次厕所开放同源。\n影响：出门找厕所、单位团建买票都会更省事，属于感受得到但不进GDP的改善。", "src": "澎湃新闻·新华网"}, {"cat": "科技", "topic": "科技", "t": "乌镇峰会：物理AI", "s": "物理AI迈向规模化落地，智能体发展自律公约发布", "b": "事实：2026年世界互联网大会乌镇峰会机器人与具身智能论坛上，京东曹鹏称物理AI已开始规模化落地，竞争焦点转向算力、数据与场景；会上发布智能体发展自律公约。\n逻辑：（推演）从会聊天到能动手，瓶颈从模型转向真实场景数据与硬件成本。\n历史：2016年AlphaGo后AI热潮集中在软件；2024年起人形机器人融资潮才把重心推向本体。\n影响：伺服、减速器、传感器等供应链岗位需求上升；自律公约意味着AI终端合规要求提前。", "src": "华尔街见闻·新浪财经"}, {"cat": "科技", "topic": "科技", "t": "产业与科研", "s": "新型显示全球市占超五成，脂肪酸代谢或有助清除衰老细胞", "b": "事实：我国新型显示行业全球市场占有率超五成；一项研究发现调节脂肪酸代谢或有助清除衰老细胞；小鹏联合高校发布GroundingPI预训练模型。\n逻辑：（推演）面板份额过半意味着议价权转移，但利润仍集中在高端材料与设备端。\n历史：2010年以前液晶面板九成靠进口，国产化用了约十年才把份额做到第一。\n影响：显示产业链的国产替代逻辑仍在，但要看材料与设备；抗衰老研究离成药尚远，别为概念付费。", "src": "华尔街见闻"}, {"cat": "财经", "topic": "股票", "t": "A股大反攻", "s": "沪指涨2.16%、科创50涨近10%，央行明日开展3000亿买断式逆回购", "b": "事实：A股午后大反攻，沪指涨2.16%，创业板指涨6.4%，科创50涨近10%，半导体板块集体爆发；央行宣布11月5日开展3000亿元买断式逆回购。\n逻辑：（推演）半导体领涨更像超跌修复叠加流动性预期，央行跨月投放对冲资金面担忧，潘功胜同日强调维护股债汇平稳运行。\n历史：2024年9月末同样出现政策定调加流动性投放驱动的单日暴涨，随后进入两个月震荡消化。\n影响：单日暴涨后追高性价比下降；持有半导体的看量能能否延续，空仓的不必一天内追完。", "src": "澎湃新闻·华尔街见闻"}, {"cat": "财经", "topic": "黄金", "t": "金银齐飙", "s": "现货金涨3%报4048美元，三季度全球央行购金创年内新高", "b": "事实：现货黄金日内涨3.0%报4048.1美元/盎司，现货白银涨4.5%报52.02美元，纽约期银涨5%；三季度全球央行购金量创年内新高，金饰需求跌至历史同期最低。\n逻辑：（推演）美元走软加美债收益率下行是直接推手，央行买金提供底部支撑，而金饰需求塌陷说明高价已挤出实物买盘。\n历史：2013年4月金价两日暴跌13%后，中国大妈抄底被套多年，实物需求从未托住趋势。\n影响：想买金饰可以等回调，别在单日大涨后追；把黄金当避险配置的，比例别超过总资产一成。", "src": "华尔街见闻·澎湃新闻"}, {"cat": "涨知识", "topic": "其他", "t": "买断式逆回购是什么", "s": "央行11月5日投放3000亿元，买断式与质押式有何不同", "b": "事实：央行公告11月5日开展3000亿元买断式逆回购操作，期限与利率待公布。\n逻辑：（推演）买断式是债券所有权真的转移给央行、到期再买回，能缓解银行缺券压力；质押式只是把券冻结。\n历史：买断式逆回购2024年10月才启用，主要用于跨月跨季流动性投放，此前工具以质押式为主。\n影响：对普通人是钱不紧、利率不飙的信号，房贷利率与理财收益短期都难大幅上行。", "src": "华尔街见闻·央行公告"}], "text": "《每日世界简报》 2026-11-04（周三）\n\n① 美中期选举落幕    民主党赢回国会控制权，特朗普承认对手取得优势\n② 中东双线升温    特朗普称对伊朗发动小规模攻击，乌方称扎波罗热空袭致37死\n③ 欧元区通胀回4%    欧元区10月CPI升至4%创三年新高，12月加息预期升温\n④ 五中全会精神落地    全国政协常委会闭幕，国办印发AI就业友好型发展方式意见\n⑤ 立法与规划密集    可再生能源法修订草案提请审议，专利商标审查十五五规划印发\n⑥ 民生两笔账    养老消费补贴惠及243万失能老人，十五五末社零约60万亿元\n⑦ 西藏强雨雪    西藏南部有强雨雪，东西两路冷空气明起南下\n⑧ 小切口便民    多地机关内部厕所常态化开放，12306上线团体票新功能\n⑨ 乌镇峰会：物理AI    物理AI迈向规模化落地，智能体发展自律公约发布\n⑩ 产业与科研    新型显示全球市占超五成，脂肪酸代谢或有助清除衰老细胞\n⑪ A股大反攻    沪指涨2.16%、科创50涨近10%，央行明日开展3000亿买断式逆回购\n⑫ 金银齐飙    现货金涨3%报4048美元，三季度全球央行购金创年内新高\n⑬ 买断式逆回购是什么    央行11月5日投放3000亿元，买断式与质押式有何不同\n\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━━\n\n① 美中期选举落幕\n 事实 ｜ 民主党赢得国会控制权，内华达州长由\n     该党福特夺回；特朗普回应称不看作个人失\n     败，因为自己名字不在选票上。\n 逻辑 ｜ （推演）国会易手后，减税与财政扩张\n     难过关，白宫转入跛脚鸭期，政策更依赖行\n     政令推进。\n 历史 ｜ 2018年中期选举共和党丢掉众议院，此\n     后两年立法基本停摆；1994年克林顿同样失\n     守两院。\n 影响 ｜ 政策不确定性下降，美股期货走高，标\n     普500期货涨约1%；但关税与科技管制走行政\n     程序，不因国会易手而停。\n\n② 中东双线升温\n 事实 ｜ 特朗普称对伊朗发动小规模攻击；乌方\n     称11月2日扎波罗热科米舒瓦斯空袭已致37人\n     死亡，搜救仍在进行。\n 逻辑 ｜ （推演）美方以有限打击维持威慑又避\n     免全面战争，油价反应克制：布伦特回落至\n     101美元下方，日内跌2.65%。\n 历史 ｜ 2020年1月美军击杀苏莱曼尼后伊朗导弹\n     报复，双方刻意控局，油价两周内回吐全部\n     涨幅。\n 影响 ｜ 原油回落意味着下一轮国内成品油调价\n     压力减轻；若霍尔木兹海峡出事，运费与油\n     价会立刻反弹。\n\n③ 欧元区通胀回4%\n 事实 ｜ 欧盟统计局初值显示，欧元区10月CPI同\n     比4.0%，高于9月的3.8%，为2023年9月以来\n     最高，能源涨幅居首；核心CPI 2.5%。\n 逻辑 ｜ （推演）通胀回到目标两倍，欧央行10\n     月按兵不动被解读为暂停而非结束，市场押\n     注12月加息。\n 历史 ｜ 2022年欧元区通胀曾破10%，欧央行一年\n     内加息450个基点，直到2023年才见顶回落。\n 影响 ｜ 加息预期推高欧元、压低美元，间接利\n     好美元计价的黄金；出口欧洲的企业要防需\n     求走弱。\n\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━━━\n\n④ 五中全会精神落地\n 事实 ｜ 全国政协十四届常委会第十九次会议4日\n     下午闭幕，主题是贯彻二十届五中全会精\n     神；国办印发关于适应人工智能技术发展助\n     力构建就业友好型发展方式的意见。\n 逻辑 ｜ （推演）把AI替代岗位提前纳入政策视\n     野，说明决策层判断冲击已到需要预案的阶\n     段。\n 历史 ｜ 2015年互联网+写入政府工作报告后，配\n     套就业与培训政策跟进约两年；这次节奏明\n     显更快。\n 影响 ｜ 转岗培训、社保衔接类政策可能加速落\n     地；对AI应用企业是合规与补贴并行的通\n     道。\n\n⑤ 立法与规划密集\n 事实 ｜ 可再生能源法修订草案提请审议；国家\n     知识产权局印发专利和商标审查十五五规\n     划；国家残疾预防行动计划2026—2030年发\n     布。\n 逻辑 ｜ （推演）新能源从鼓励装机转向入市消\n     纳，法律层面要为绿电交易与储能责任划清\n     边界。\n 历史 ｜ 2005年可再生能源法首立、2009年修正\n     确立全额保障性收购，每次修订都对应一轮\n     装机结构变化。\n 影响 ｜ 光伏风电的电价机制与消纳责任可能再\n     调整，持有新能源电站或相关基金的人要留\n     意细则。\n\n⑥ 民生两笔账\n 事实 ｜ 养老服务消费补贴已惠及243万失能老年\n     人；央视报道十五五末社会消费品零售总额\n     将达约60万亿元。\n 逻辑 ｜ （推演）补贴直接补给失能老人家庭，\n     等于用财政把照护需求变成可支付的服务消\n     费。\n 历史 ｜ 2020年起多地试点长期护理保险，参保\n     人照护支出自付比例平均降约三成。\n 影响 ｜ 家里有失能老人的可关注本地补贴申领\n     口径；服务消费是下一阶段政策重点。\n\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━━\n\n⑦ 西藏强雨雪\n 事实 ｜ 中央气象台提示西藏南部等地有强雨\n     雪，明起东西两路冷空气将南下；两部门已\n     部署西藏强降雪天气防范应对。\n 逻辑 ｜ （推演）高原强降雪叠加震区安置，救\n     灾难度高于平原；两路冷空气夹击会让中东\n     部降温更明显。\n 历史 ｜ 2023年12月甘肃积石山地震后同样遇寒\n     潮，低温一度成为救援最大变量。\n 影响 ｜ 未来三天高原与西北出行要防封路；中\n     东部昼夜温差拉大，心脑血管人群注意保\n     暖。\n\n⑧ 小切口便民\n 事实 ｜ 多地机关单位内部厕所常态化对外开\n     放；铁路12306上线新功能，买团体票更方\n     便；国内最长地铁环线全线开通。\n 逻辑 ｜ （推演）公共资源错时共享成本低、见\n     效快，是城市治理里少见的低争议增量。\n 历史 ｜ 2018年起多地推行机关停车场夜间开\n     放，做法与此次厕所开放同源。\n 影响 ｜ 出门找厕所、单位团建买票都会更省\n     事，属于感受得到但不进GDP的改善。\n\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━━\n\n⑨ 乌镇峰会：物理AI\n 事实 ｜ 2026年世界互联网大会乌镇峰会机器人\n     与具身智能论坛上，京东曹鹏称物理AI已开\n     始规模化落地，竞争焦点转向算力、数据与\n     场景；会上发布智能体发展自律公约。\n 逻辑 ｜ （推演）从会聊天到能动手，瓶颈从模\n     型转向真实场景数据与硬件成本。\n 历史 ｜ 2016年AlphaGo后AI热潮集中在软件；\n     2024年起人形机器人融资潮才把重心推向本\n     体。\n 影响 ｜ 伺服、减速器、传感器等供应链岗位需\n     求上升；自律公约意味着AI终端合规要求提\n     前。\n\n⑩ 产业与科研\n 事实 ｜ 我国新型显示行业全球市场占有率超五\n     成；一项研究发现调节脂肪酸代谢或有助清\n     除衰老细胞；小鹏联合高校发布GroundingPI\n     预训练模型。\n 逻辑 ｜ （推演）面板份额过半意味着议价权转\n     移，但利润仍集中在高端材料与设备端。\n 历史 ｜ 2010年以前液晶面板九成靠进口，国产\n     化用了约十年才把份额做到第一。\n 影响 ｜ 显示产业链的国产替代逻辑仍在，但要\n     看材料与设备；抗衰老研究离成药尚远，别\n     为概念付费。\n\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━━\n\n⑪ A股大反攻\n 事实 ｜ A股午后大反攻，沪指涨2.16%，创业板\n     指涨6.4%，科创50涨近10%，半导体板块集体\n     爆发；央行宣布11月5日开展3000亿元买断式\n     逆回购。\n 逻辑 ｜ （推演）半导体领涨更像超跌修复叠加\n     流动性预期，央行跨月投放对冲资金面担\n     忧，潘功胜同日强调维护股债汇平稳运行。\n 历史 ｜ 2024年9月末同样出现政策定调加流动性\n     投放驱动的单日暴涨，随后进入两个月震荡\n     消化。\n 影响 ｜ 单日暴涨后追高性价比下降；持有半导\n     体的看量能能否延续，空仓的不必一天内追\n     完。\n\n⑫ 金银齐飙\n 事实 ｜ 现货黄金日内涨3.0%报4048.1美元/盎\n     司，现货白银涨4.5%报52.02美元，纽约期银\n     涨5%；三季度全球央行购金量创年内新高，\n     金饰需求跌至历史同期最低。\n 逻辑 ｜ （推演）美元走软加美债收益率下行是\n     直接推手，央行买金提供底部支撑，而金饰\n     需求塌陷说明高价已挤出实物买盘。\n 历史 ｜ 2013年4月金价两日暴跌13%后，中国大\n     妈抄底被套多年，实物需求从未托住趋势。\n 影响 ｜ 想买金饰可以等回调，别在单日大涨后\n     追；把黄金当避险配置的，比例别超过总资\n     产一成。\n\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━━\n\n⑬ 买断式逆回购是什么\n 事实 ｜ 央行公告11月5日开展3000亿元买断式逆\n     回购操作，期限与利率待公布。\n 逻辑 ｜ （推演）买断式是债券所有权真的转移\n     给央行、到期再买回，能缓解银行缺券压\n     力；质押式只是把券冻结。\n 历史 ｜ 买断式逆回购2024年10月才启用，主要\n     用于跨月跨季流动性投放，此前工具以质押\n     式为主。\n 影响 ｜ 对普通人是钱不紧、利率不飙的信号，\n     房贷利率与理财收益短期都难大幅上行。\n\n📰 网页版精读+申论金句：https://zjb-cloud.github.io/kaogong/ → 📰 每日新闻\n"}, {"id": 5, "date": "2026-11-05", "title": "每日世界简报 · 2026-11-05", "summary": "美国中期选举翻蓝 · 霍尔木兹油轮触雷 · 春节连休9天 · 汇金类平准基金", "author": "聪明仔", "items": [{"cat": "国际", "topic": "国际", "t": "美国中期选举翻蓝", "s": "民主党多州翻盘，特朗普首次亮相，党内开始找替罪羊", "b": "事实：美国中期选举结果出炉，民主党在多个州翻盘，澎湃新闻称共和党从得州到锈带的\"94年不败\"版图被打破；特朗普选后首次公开露面，称或能与民主党人相处融洽。\n逻辑：（推演）共和党内部把失利归咎于防长赫格塞思，CNN称部分议员最快下周推动弹劾防长——短期对外更强硬以转移矛盾，是这类内斗的常见出口。\n历史：2018年中期选举共和党丢掉众议院后，特朗普转向关税与边境议题巩固基本盘；1994年\"共和党革命\"是反向一例，执政党中期大败后政策往往更趋极端。\n影响：美国对伊朗、对华政策的不确定性上升，油价与关税两条线都可能反复；普通人的感受是进口商品价格和出境行程的波动更频繁。", "src": "澎湃新闻 / 金十数据"}, {"cat": "国际", "topic": "国际", "t": "欧洲多国航班遭诈弹", "s": "维也纳、布拉格、华沙等地航班受威胁，均未获证实", "b": "事实：11月5日欧洲多国航班接连收到炸弹威胁：维也纳机场4个航班受影响，捷克4架飞布拉格客机接受检查，芬兰航空2架、波兰航空1架警戒降落，威胁均未获证实。\n逻辑：（推演）同一时段多国同时\"诈弹\"，成本极低、扰动极大；无论彼此是否关联，欧洲机场安检与调度都会长期加码，误机与安检排队变长会成为常态。\n历史：2010年\"也门包裹炸弹\"事件后全球货运安检升级；2024年欧洲多国也出现过一波虚假炸弹威胁。\n影响：近期赴欧出差旅游，转机时间要留足，保险条款里\"恐怖威胁导致延误\"的理赔范围要提前看清。", "src": "金十数据"}, {"cat": "国际", "topic": "能源", "t": "霍尔木兹油轮触雷", "s": "布伦特原油涨破96美元，韩国拟扩大护航范围", "b": "事实：伊朗革命卫队海军称，5日上午一艘油轮在霍尔木兹海峡以东触雷起火；另有一艘油轮在卡塔尔北部海域被不明飞行物击中。布伦特原油涨1.5%破96美元/桶。\n逻辑：（推演）海峡承载全球约五分之一的海运原油，任何\"触雷\"都是保险费率与运价的开关；韩国已拟把护航区域扩至阿曼南部海域，军事存在越多越易擦枪走火。\n历史：2019年阿曼湾油轮遇袭与沙特阿美油田被袭，布伦特单日跳涨约15%；1980年代\"油轮战\"曾让海峡险情常态化。\n影响：油价上冲会推高航空燃油与物流成本，国内成品油调价窗口跟涨概率上升；化工、航运板块波动加大。", "src": "金十数据 / 华尔街见闻"}, {"cat": "国内·政策", "topic": "政策", "t": "第九届进博会开幕", "s": "上海开幕，中国馆亮出火箭海上回收模型等展品", "b": "事实：第九届中国国际进口博览会11月5日在上海开幕，新华社称\"历九弥新\"；中国馆展出火箭海上回收装置模型、张雪机车等展品，澎湃称\"在中国，为全球\"成共识。\n逻辑：（推演）在外部关税摩擦未解的背景下，进博会既是\"开门\"的姿态，也是把采购订单当谈判筹码的场合；展品从消费品转向高端装备，说明瞄准的是产业资本。\n历史：2018年首届进博会以来历届都伴随扩大进口与降税清单，2019年第二届公布意向成交超700亿美元。\n影响：进口食品、医疗器械的渠道价可能松动，跨境电商与免税渠道选择更多；做外贸的这是一年里最集中的接单窗口。", "src": "新华网 / 澎湃新闻"}, {"cat": "国内·政策", "topic": "民生", "t": "2027年放假安排出炉", "s": "春节连休9天，全年仅3个节假日需调休", "b": "事实：2027年放假安排公布：春节连休9天，全年仅3个节假日需要调休，端午、中秋不调休各放假1天，澎湃称调休天数明显减少。\n逻辑：（推演）调休被诟病多年，\"少挪假\"是用很小的成本换民意；但假期总量没变、仍集中在春节，旅游与消费的峰谷差还是那么大，机票酒店照样\"两头贵\"。\n历史：1999年为刺激消费设立黄金周，2013年取消五一黄金周改小长假，2025年起法定假日增至13天，方向一直是\"少挪、多真休\"。\n影响：明年春节请两天可拼出11天长假，出境游和返乡票要尽早订；景区与铁路的最高峰仍在初五到初七。", "src": "澎湃新闻 / 百度热搜"}, {"cat": "国内·民生", "topic": "民生", "t": "养老补贴惠及243万人", "s": "核销93.3亿元，带动养老服务消费404.7亿元", "b": "事实：民政部：截至9月底，向中度以上失能老年人发放的养老服务消费补贴累计核销93.3亿元，带动养老服务消费404.7亿元，243万失能老年人受益。\n逻辑：（推演）补贴不是发钱，而是\"指定用途的消费券\"，用财政撬动护理服务市场；一元补贴约拉动四块三消费，杠杆很高，但服务供给不足的地方券发不出去。\n历史：2022年起多地试点长期护理保险，日本2000年介护保险是同类制度样板，共同点是\"先建服务网络再给钱\"。\n影响：家里有失能老人的，去街道问清本地申领口径；养老护理员、康复辅具租赁是这两年的就业与生意点。", "src": "新华网 / 民政部"}, {"cat": "国内·生活", "topic": "天气", "t": "中东部大范围雨雪", "s": "气温大面积创新低，7日华北北部有暴雪", "b": "事实：中央气象台：11月5日至10日全国大部降温，气温大面积创今年下半年来新低；7日华北北部有暴雪，长江中下游大到暴雨，广州9日前后最高温跌到25℃。\n逻辑：（推演）冷空气叠加降水，湿冷比干冷更伤人；长春明天最高温跌破冰点，为当地下半年首次，入冬进程偏早，取暖与用电负荷会提前抬升。\n历史：2021年11月初的寒潮曾让华北一夜入冬、多地提前供暖，当年动力煤价格与天然气需求同步走高。\n影响：北方留意供暖试水，南方备好取暖电器；雨雪过后一到两周菜价通常上行，叶菜最先涨。", "src": "新华网 / 中央气象台"}, {"cat": "国内·生活", "topic": "科技", "t": "高校AI巡课引争议", "s": "可识别到课率、抬头率、前排就座率，被质疑电子监工", "b": "事实：澎湃报道，多所高校已引入AI教学督导巡课系统，可识别到课率、抬头率、前排就座率；同期媒体批评环卫工佩戴定位工牌是\"电子监工\"。\n逻辑：（推演）摄像头加姿态识别把\"课堂状态\"变成可考核数据，短期抬高抬头率，长期可能诱导表演式听课；指标一旦进绩效，老师会把精力放在\"被看见\"上。\n历史：2019年多所高校试水人脸识别签到引发争议，2021年教育部曾明确限制进校园的人脸识别应用。\n影响：学生要留意自己的影像数据流向，可依《个人信息保护法》要求学校说明采集目的与保存期限。", "src": "澎湃新闻"}, {"cat": "科技", "topic": "医疗", "t": "北京首款CAR-T获批", "s": "治疗复发难治性大B细胞淋巴瘤，北京首款", "b": "事实：北京艺妙神州的泊基奥仑赛注射液获国家药监局药品注册证书，用于二线及以上治疗后成人复发或难治性大B细胞淋巴瘤，是北京市首款获批的CAR-T细胞药品。\n逻辑：（推演）CAR-T是\"一人一药\"的定制疗法，产能与成本卡在病毒载体和冷链上，获批不等于可及；国产化的真正意义，是把百万级的价格往下压。\n历史：2021年国内首批CAR-T上市时定价约120万元一针，2023年起多款陆续进入地方惠民保与商保。\n影响：患者端最实际的是\"进没进惠民保、商保报不报\"，关注点不该是新闻热度，而是本地医保目录与援助项目。", "src": "北京日报 / 华尔街见闻"}, {"cat": "科技", "topic": "科技", "t": "Kimi K3.1 Pro开源", "s": "2.8万亿参数、上下文100万token，完整权重公开", "b": "事实：11月5日Kimi K3.1 Pro完整权重公开：总参数2.8万亿、激活1040亿、上下文100万token，采用MXFP4低精度量化，16位精度存储约需5.6TB，配套放出许可证。\n逻辑：（推演）权重开放意味着下游能自己部署、自己微调，云端API的护城河从\"模型\"退到\"算力+工程\"；低精度量化是让万亿模型跑在国产卡上的关键一步。\n历史：2023年Llama 2开源后全球出现一波\"套壳创业\"随后洗牌；2025年DeepSeek开源直接把推理价格打下来。\n影响：普通人短期受益是免费AI工具更多更好用；炒股的人要明白，算力、存储与推理成本的价格战还没结束。", "src": "华尔街见闻"}, {"cat": "财经", "topic": "股票", "t": "汇金\"类平准基金\"", "s": "国务院金融报告定调，回购增持再贷款加力", "b": "事实：国务院关于金融工作情况的报告提出，支持中央汇金公司发挥\"类平准基金\"作用，巩固完善资本市场稳市机制；央视同日报道央行加力实施股票回购增持再贷款。\n逻辑：（推演）\"类平准基金\"是给市场一个明确的对手盘承诺，重点不在买多少，而在\"跌了有人接\"的预期；回购增持再贷款则是用低成本资金让公司买自己。\n历史：2015年股灾时证金公司入场买股；2024年10月央行设立首期3000亿元股票回购增持再贷款，利率1.75%。\n影响：指数大幅下挫时被托底的概率提升，但托底不等于普涨；有回购公告、有专项贷款的公司，比\"喊话式增持\"可靠得多。", "src": "澎湃新闻 / 央视新闻"}, {"cat": "财经", "topic": "股票", "t": "A股成交2.1万亿", "s": "三大股指集体收涨，冲高回落获利盘兑现", "b": "事实：11月5日A股冲高回落，三大股指集体收涨，两市成交2.1万亿元；盘面获利盘兑现明显，权重与题材分化。\n逻辑：（推演）两万亿以上成交说明分歧极大，冲高回落是\"有人接、也有人跑\"；在类平准基金与回购政策加持下，指数下沿有支撑，上沿看增量资金能否续上。\n历史：2024年10月也曾出现连续两万亿成交后高位震荡，随后进入长达数月的箱体整理。\n影响：追高的短线客这两天最容易两头挨打，控制仓位、留住现金，比猜方向更实际。", "src": "澎湃新闻"}, {"cat": "财经", "topic": "国际", "t": "欧洲12月或加息", "s": "欧央行管委称可能性相当大，9月PPI同比11.1%", "b": "事实：欧洲央行管委齐格曼称12月加息可能性\"相当大\"，并称现在说还需收紧多少为时过早；欧元区9月PPI同比11.1%（预期10.6%、前值8.2%），环比2.5%。\n逻辑：（推演）PPI远超预期，说明能源与中间品价格正在重新传导；英国10月建筑业PMI跌到43.6，是典型\"滞胀\"组合——加息压通胀，同时压增长。\n历史：2022年欧央行曾一次加息75个基点对抗能源通胀，代价是欧元区滑入技术性衰退。\n影响：欧元走强、人民币相对承压，出口企业结汇时点更讲究；做欧线外贸的，要同时盯订单和汇率两头。", "src": "金十数据 / 华尔街见闻"}, {"cat": "涨知识", "topic": "历史", "t": "央行\"各走各路\"", "s": "欧洲要加息、美国在谈降息，汇率成主要风险源", "b": "事实：同一天：欧洲央行暗示12月可能加息，挪威央行称必要时准备加息；而美国10月挑战者企业裁员人数同比下降71.3%，市场仍在讨论降息节奏。\n逻辑：（推演）通胀来源不同，药方就不同——欧洲是能源推着PPI走，美国是就业在降温；全球\"同步加息\"的年代结束，汇率波动取代利率同步，成为主要风险源。\n历史：1980年代沃尔克用20%的利率制服通胀，代价是拉美债务危机；2022至2023年全球同步加息，随后又集体转向降息，政策从来不是一条直线。\n影响：利差决定资金流向，进而影响A股外资与港股弹性；换外汇、买QDII的人，别只盯一个国家的央行。", "src": "金十数据 / 华尔街见闻"}], "text": "《每日世界简报》 2026-11-05（周四）\n\n① 美国中期选举翻蓝    民主党大胜，特朗普首次亮相，党内开始找\"替罪羊\"\n② 欧洲多国航班遭诈弹    维也纳、布拉格、华沙等地航班受威胁，均未证实\n③ 霍尔木兹油轮触雷    布伦特原油涨破96美元，韩国拟扩大护航范围\n④ 第九届进博会开幕    \"在中国，为全球\"成共识，中国馆亮出火箭回收模型\n⑤ 2027年放假安排出炉    春节连休9天，仅3个节假日调休\n⑥ 养老补贴惠及243万人    核销93.3亿元，带动养老服务消费404.7亿元\n⑦ 中东部大范围雨雪    气温大面积创新低，7日华北北部有暴雪\n⑧ 高校AI巡课引争议    可识别到课率、抬头率、前排就座率\n⑨ 北京首款CAR-T获批    治疗复发难治性大B细胞淋巴瘤\n⑩ Kimi K3.1 Pro开源    2.8万亿参数，上下文100万token\n⑪ 汇金\"类平准基金\"    国务院金融报告定调，回购增持再贷款加力\n⑫ A股成交2.1万亿    三大股指收涨，冲高回落获利兑现\n⑬ 欧洲12月或加息    欧元区9月PPI同比11.1%，远超预期\n⑭ 央行\"各走各路\"    欧洲要加息、美国在谈降息，汇率成主要风险源\n\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━━\n\n① 美国中期选举翻蓝\n 事实 ｜ 美国中期选举结果出炉，民主党在多个州翻盘，澎湃\n     新闻称共和党从得州到锈带的\"94年不败\"版图被打破；\n     特朗普选后首次公开露面，称或能与民主党人相处融洽。\n 逻辑 ｜ （推演）共和党内部把失利归咎于防长赫格塞思，CNN\n     称部分议员最快下周推动弹劾防长——短期对外更强硬\n     以转移矛盾，是这类内斗的常见出口。\n 历史 ｜ 2018年中期选举共和党丢掉众议院后，特朗普转向关税\n     与边境议题巩固基本盘；1994年\"共和党革命\"是反向\n     一例，执政党中期大败后政策往往更趋极端。\n 影响 ｜ 美国对伊朗、对华政策的不确定性上升，油价与关税\n     两条线都可能反复；普通人的感受是进口商品价格和\n     出境行程的波动更频繁。\n\n② 欧洲多国航班遭诈弹\n 事实 ｜ 11月5日欧洲多国航班接连收到炸弹威胁：维也纳机场\n     4个航班受影响，捷克4架飞布拉格客机接受检查，芬兰\n     航空2架、波兰航空1架警戒降落，威胁均未获证实。\n 逻辑 ｜ （推演）同一时段多国同时\"诈弹\"，成本极低、扰动\n     极大；无论彼此是否关联，欧洲机场安检与调度都会\n     长期加码，误机与安检排队变长会成为常态。\n 历史 ｜ 2010年\"也门包裹炸弹\"事件后全球货运安检升级；\n     2024年欧洲多国也出现过一波虚假炸弹威胁。\n 影响 ｜ 近期赴欧出差旅游，转机时间要留足，保险条款里\n     \"恐怖威胁导致延误\"的理赔范围要提前看清。\n\n③ 霍尔木兹油轮触雷\n 事实 ｜ 伊朗革命卫队海军称，5日上午一艘油轮在霍尔木兹\n     海峡以东触雷起火；另有一艘油轮在卡塔尔北部海域\n     被不明飞行物击中。布伦特原油涨1.5%破96美元/桶。\n 逻辑 ｜ （推演）海峡承载全球约五分之一的海运原油，任何\n     \"触雷\"都是保险费率与运价的开关；韩国已拟把护航\n     区域扩至阿曼南部海域，军事存在越多越易擦枪走火。\n 历史 ｜ 2019年阿曼湾油轮遇袭与沙特阿美油田被袭，布伦特\n     单日跳涨约15%；1980年代\"油轮战\"曾让海峡险情\n     常态化，保险与绕行成本长期抬升。\n 影响 ｜ 油价上冲会推高航空燃油与物流成本，国内成品油\n     调价窗口跟涨概率上升；化工、航运板块波动加大。\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━━━\n\n④ 第九届进博会开幕\n 事实 ｜ 第九届中国国际进口博览会11月5日在上海开幕，新华\n     社称\"历九弥新\"；中国馆展出火箭海上回收装置模型、\n     张雪机车等展品，澎湃称\"在中国，为全球\"成共识。\n 逻辑 ｜ （推演）在外部关税摩擦未解的背景下，进博会既是\n     \"开门\"的姿态，也是把采购订单当谈判筹码的场合；\n     展品从消费品转向高端装备，说明瞄准的是产业资本。\n 历史 ｜ 2018年首届进博会以来历届都伴随扩大进口与降税\n     清单，2019年第二届公布意向成交超700亿美元。\n 影响 ｜ 进口食品、医疗器械的渠道价可能松动，跨境电商与\n     免税渠道选择更多；做外贸的这是一年里最集中的\n     接单窗口。\n\n⑤ 2027年放假安排出炉\n 事实 ｜ 2027年放假安排公布：春节连休9天，全年仅3个节假\n     日需要调休，端午、中秋不调休各放假1天，澎湃称\n     调休天数明显减少。\n 逻辑 ｜ （推演）调休被诟病多年，\"少挪假\"是用很小的成本\n     换民意；但假期总量没变、仍集中在春节，旅游与\n     消费的峰谷差还是那么大，机票酒店照样\"两头贵\"。\n 历史 ｜ 1999年为刺激消费设立黄金周，2013年取消五一黄金\n     周改小长假，2025年起法定假日增至13天，方向一直\n     是\"少挪、多真休\"。\n 影响 ｜ 明年春节请两天可拼出11天长假，出境游和返乡票要\n     尽早订；景区与铁路的最高峰仍在初五到初七。\n\n⑥ 养老补贴惠及243万人\n 事实 ｜ 民政部：截至9月底，向中度以上失能老年人发放的\n     养老服务消费补贴累计核销93.3亿元，带动养老服务\n     消费404.7亿元，243万失能老年人受益。\n 逻辑 ｜ （推演）补贴不是发钱，而是\"指定用途的消费券\"，\n     用财政撬动护理服务市场；一元补贴约拉动四块三\n     消费，杠杆很高，但服务供给不足的地方券发不出去。\n 历史 ｜ 2022年起多地试点长期护理保险，日本2000年介护保险\n     是同类制度样板，共同点是\"先建服务网络再给钱\"。\n 影响 ｜ 家里有失能老人的，去街道问清本地申领口径；\n     养老护理员、康复辅具租赁是这两年的就业与生意点。\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━━\n\n⑦ 中东部大范围雨雪\n 事实 ｜ 中央气象台：11月5日至10日全国大部降温，气温大面积\n     创今年下半年来新低；7日华北北部有暴雪，长江中\n     下游大到暴雨，广州9日前后最高温跌到25℃。\n 逻辑 ｜ （推演）冷空气叠加降水，湿冷比干冷更伤人；长春\n     明天最高温跌破冰点，为当地下半年首次，入冬进程\n     偏早，取暖与用电负荷会提前抬升。\n 历史 ｜ 2021年11月初的寒潮曾让华北一夜入冬、多地提前\n     供暖，当年动力煤价格与天然气需求同步走高。\n 影响 ｜ 北方留意供暖试水，南方备好取暖电器；雨雪过后\n     一到两周菜价通常上行，叶菜最先涨。\n\n⑧ 高校AI巡课引争议\n 事实 ｜ 澎湃报道，多所高校已引入AI教学督导巡课系统，\n     可识别到课率、抬头率、前排就座率；同期媒体批评\n     环卫工佩戴定位工牌是\"电子监工\"。\n 逻辑 ｜ （推演）摄像头加姿态识别把\"课堂状态\"变成可考核\n     数据，短期抬高抬头率，长期可能诱导表演式听课；\n     指标一旦进绩效，老师会把精力放在\"被看见\"上。\n 历史 ｜ 2019年多所高校试水人脸识别签到引发争议，2021年\n     教育部曾明确限制进校园的人脸识别应用。\n 影响 ｜ 学生要留意自己的影像数据流向，可依《个人信息\n     保护法》要求学校说明采集目的与保存期限。\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━━\n\n⑨ 北京首款CAR-T获批\n 事实 ｜ 北京艺妙神州的泊基奥仑赛注射液获国家药监局药品\n     注册证书，用于二线及以上治疗后成人复发或难治性\n     大B细胞淋巴瘤，是北京市首款获批的CAR-T细胞药品。\n 逻辑 ｜ （推演）CAR-T是\"一人一药\"的定制疗法，产能与成本\n     卡在病毒载体和冷链上，获批不等于可及；国产化\n     的真正意义，是把百万级的价格往下压。\n 历史 ｜ 2021年国内首批CAR-T上市时定价约120万元一针，\n     2023年起多款陆续进入地方惠民保与商保。\n 影响 ｜ 患者端最实际的是\"进没进惠民保、商保报不报\"，\n     关注点不该是新闻热度，而是本地医保目录与援助\n     项目。\n\n⑩ Kimi K3.1 Pro开源\n 事实 ｜ 11月5日Kimi K3.1 Pro完整权重公开：总参数2.8万亿、\n     激活1040亿、上下文100万token，采用MXFP4低精度\n     量化，16位精度存储约需5.6TB，配套放出许可证。\n 逻辑 ｜ （推演）权重开放意味着下游能自己部署、自己微调，\n     云端API的护城河从\"模型\"退到\"算力+工程\"；低精度\n     量化是让万亿模型跑在国产卡上的关键一步。\n 历史 ｜ 2023年Llama 2开源后全球出现一波\"套壳创业\"随后\n     洗牌；2025年DeepSeek开源直接把推理价格打下来。\n 影响 ｜ 普通人短期受益是免费AI工具更多更好用；炒股的人\n     要明白，算力、存储与推理成本的价格战还没结束。\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━━\n\n⑪ 汇金\"类平准基金\"\n 事实 ｜ 国务院关于金融工作情况的报告提出，支持中央汇金\n     公司发挥\"类平准基金\"作用，巩固完善资本市场稳市\n     机制；央视同日报道央行加力实施股票回购增持再贷款。\n 逻辑 ｜ （推演）\"类平准基金\"是给市场一个明确的对手盘\n     承诺，重点不在买多少，而在\"跌了有人接\"的预期；\n     回购增持再贷款则是用低成本资金让公司买自己。\n 历史 ｜ 2015年股灾时证金公司入场买股；2024年10月央行设立\n     首期3000亿元股票回购增持再贷款，利率1.75%。\n 影响 ｜ 指数大幅下挫时被托底的概率提升，但托底不等于\n     普涨；有回购公告、有专项贷款的公司，比\"喊话式\n     增持\"可靠得多。\n\n⑫ A股成交2.1万亿\n 事实 ｜ 11月5日A股冲高回落，三大股指集体收涨，两市成交\n     2.1万亿元；盘面获利盘兑现明显，权重与题材分化。\n 逻辑 ｜ （推演）两万亿以上成交说明分歧极大，冲高回落是\n     \"有人接、也有人跑\"；在类平准基金与回购政策加持\n     下，指数下沿有支撑，上沿看增量资金能否续上。\n 历史 ｜ 2024年10月也曾出现连续两万亿成交后高位震荡，\n     随后进入长达数月的箱体整理。\n 影响 ｜ 追高的短线客这两天最容易两头挨打，控制仓位、\n     留住现金，比猜方向更实际。\n\n⑬ 欧洲12月或加息\n 事实 ｜ 欧洲央行管委齐格曼称12月加息可能性\"相当大\"，并\n     称现在说还需收紧多少为时过早；欧元区9月PPI同比\n     11.1%（预期10.6%、前值8.2%），环比2.5%。\n 逻辑 ｜ （推演）PPI远超预期，说明能源与中间品价格正在\n     重新传导；英国10月建筑业PMI跌到43.6，是典型\n     \"滞胀\"组合——加息压通胀，同时压增长。\n 历史 ｜ 2022年欧央行曾一次加息75个基点对抗能源通胀，\n     代价是欧元区滑入技术性衰退。\n 影响 ｜ 欧元走强、人民币相对承压，出口企业结汇时点更\n     讲究；做欧线外贸的，要同时盯订单和汇率两头。\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━━\n\n⑭ 央行\"各走各路\"\n 事实 ｜ 同一天：欧洲央行暗示12月可能加息，挪威央行称\n     必要时准备加息；而美国10月挑战者企业裁员人数\n     同比下降71.3%，市场仍在讨论降息节奏。\n 逻辑 ｜ （推演）通胀来源不同，药方就不同——欧洲是能源\n     推着PPI走，美国是就业在降温；全球\"同步加息\"的\n     年代结束，汇率波动取代利率同步，成为主要风险源。\n 历史 ｜ 1980年代沃尔克用20%的利率制服通胀，代价是拉美\n     债务危机；2022至2023年全球同步加息，随后又集体\n     转向降息，政策从来不是一条直线。\n 影响 ｜ 利差决定资金流向，进而影响A股外资与港股弹性；\n     换外汇、买QDII的人，别只盯一个国家的央行。\n\n─────────────────────────────\n想深挖哪条说一声。"}, {"id": 6, "date": "2026-11-06", "title": "每日世界简报 · 2026-11-06", "summary": "反跨境腐败法通过 · 首个暴雪预警 · 储蓄国债开卖 · 全球黑色星期五", "author": "聪明仔", "items": [{"cat": "国际", "topic": "国际", "t": "加蓬总统访华", "s": "习近平举行欢迎仪式，中非合作再落一子", "b": "事实：11月6日习近平举行仪式，欢迎加蓬总统恩圭马访华，双方将谈双边关系与中非合作。\n逻辑：（推演）加蓬是非洲产油国与锰矿出口国，中方密集接待非洲元首，意在长期锁定矿产与能源。\n历史：2023年加蓬政变后西方暂停部分援助，中国仍维持不干涉内政的合作模式，与以往处理方式一致。\n影响：直接影响小，但锰、铀、原油的长期采购会影响国内钢材与电池成本。", "src": "华尔街见闻"}, {"cat": "国际", "topic": "国际", "t": "以色列对美停援震惊", "s": "美以关系出现公开裂痕，中东溢价抬头", "b": "事实：11月6日以色列总统称，对美国拟停止军事援助感到震惊；同日以阿拉伯裔政党正推动扳倒内塔尼亚胡。\n逻辑：（推演）美国国内政治周期与战事成本上升，让援助从战略承诺变成可议价筹码。\n历史：2016年美以签十年380亿美元军援备忘录，援助历来附带条件，并非无条件赠与。\n影响：中东风险溢价推高油价与航运保险，国内成品油、航空与化工成本跟着波动。", "src": "华尔街见闻 / 澎湃新闻"}, {"cat": "国际", "topic": "国际", "t": "希腊沉船59人失踪", "s": "60名非法移民仅1人获救，东地中海再酿惨剧", "b": "事实：载60名非法移民的船3日在希腊克里特岛东南海域沉没，截至5日仅1人获救、59人失踪，搜救仍在继续。\n逻辑：（推演）东地中海航线因利比亚、埃及局势外溢更拥挤；欧盟把边界外包后，救援与遣返互相推诿。\n历史：2015年4月地中海两起沉船致超700人死亡，此后欧盟—土耳其协议压住东线，中线死亡率反升。\n影响：与国内生活关联弱，但会强化欧洲边境管控议题，间接影响中欧贸易摩擦的节奏。", "src": "新华社"}, {"cat": "国内·政策", "topic": "政策", "t": "反跨境腐败法表决通过", "s": "6章47条，国家监委牵头，追逃追赃补上国内法拼图", "b": "事实：全国人大常委会11月6日表决通过反跨境腐败法，共6章47条，含机制职责、案件办理与国际合作、廉洁合规、法律责任。\n逻辑：（推演）过去追逃靠个案协商，缺国内法授权与跨境取证程序；立法后可对接国际公约，形成固定流程。\n历史：2015年公布百名红通，早期多靠劝返；2018年国家监委成立后才有统一对外办案主体。\n影响：普通人无直接负担，但外贸与跨境电商的境外账户、代理支付合规审查会趋严。", "src": "新华社 / 新浪财经"}, {"cat": "国内·政策", "topic": "政策", "t": "账款披露新规", "s": "账期写进债券披露，替中小企业讨“60日付现”", "b": "事实：11月6日交易商协会发文，发行人须披露近一年应付账款余额、账期分布与周转天数，鼓励践行“60日付现承诺”。\n逻辑：（推演）大企业用商业信用免费融资，把账期写进债券披露，等于让投资人替中小企业监督。\n历史：2020年《保障中小企业款项支付条例》已定“一般不超60日”，但缺披露口径，执行靠举报。\n影响：若真落地，中小供应商回款变快、现金流改善；大企业营运资金承压。", "src": "金十数据 / 华尔街见闻"}, {"cat": "国内·政策", "topic": "房地产", "t": "京渝同步松绑住房", "s": "从控房价转向稳总量，改善性需求被反复点名", "b": "事实：11月6日北京提出2030年城镇住房总量保持稳定、供给结构与需求更适配，鼓励刚性与改善性需求；同日重庆出台商品住房销售新政。\n逻辑：（推演）政策目标从控房价转向稳总量、调结构，说明重心已由抑需求变为防失速。\n历史：2016年“930”、2017年“317”是收紧起点；2022年以来松绑超千次，成交修复仍弱于预期。\n影响：想换房的可等细则（税费、二套认定）；城市分化会更大；地产链是情绪利好，仍看销售数据。", "src": "华尔街见闻 / 澎湃新闻"}, {"cat": "国内·生活", "topic": "天气", "t": "下半年首个暴雪预警", "s": "北京发黄色信号，周六雪强达峰，出行与菜价先受影响", "b": "事实：11月6日18时中央气象台发布暴雪蓝色预警，为下半年首个；北京同步发布黄色预警，7日中午至8日上午多区大雪到暴雪，局地积雪可达8厘米以上。\n逻辑：（推演）11月上旬华北暴雪，是暖湿气流异常北推叠加冷空气南下；真正的风险点在结冰与早高峰重叠。\n历史：2021年11月6—8日华北罕见暴雪致交通瘫痪；2012年北京“7·21”暴露过应急调度短板。\n影响：周末避开山区与高速；京津冀快递、蔬菜运输或延迟1—2天，菜价短期小涨。", "src": "金十数据 / 新浪财经"}, {"cat": "国内·生活", "topic": "消费", "t": "2027年9天春节长假", "s": "调休拼长假，机票酒店已开始前置涨价", "b": "事实：2027年放假安排公布，春节形成9天超长假期，旅游平台已出现除夕前一日机票下单。\n逻辑：（推演）用调休拼长假，是用集中假期刺激服务消费，把分散休息日换成可出行的整块时间。\n历史：1999年设黄金周，2008年增清明、五一、中秋小长假，每次调整都伴随出行峰值与承载争议。\n影响：除夕前一日机票、热门城市酒店会先涨；景区民宿弹性大，但前后周末要连上更长的班。", "src": "澎湃新闻"}, {"cat": "科技", "topic": "科技", "t": "造出最冷人造物质", "s": "我国科学家再破纪录，超冷原子是量子技术底座", "b": "事实：澎湃新闻11月6日报道，我国科学家造出目前已知最冷的人造物质，成果已发表，具体温度与装置以论文为准。\n逻辑：（推演）超冷原子是量子计算、原子钟与精密测量的底座；温度再低一个量级，相干时间更长、噪声更低。\n历史：1995年实现玻色—爱因斯坦凝聚，2001年获诺奖；中国2010年后靠超冷费米气体追赶。\n影响：短期无消费级产品，长期影响量子传感、导航与高端仪器的进口替代。", "src": "澎湃新闻"}, {"cat": "科技", "topic": "科技", "t": "英伟达芯片被劫", "s": "7605万元货物被假卡车拉走，AI芯片黑市链条浮现", "b": "事实：加州奥克兰警方调查英伟达硬件被盗案，涉值1140万美元（约7605万元），货物被伪装成食品运输的卡车接走后失踪。\n逻辑：（推演）AI芯片黑市已形成订单—伪造承运—跨境转卖链条，物流是验证最薄弱的一环。\n历史：2023年以来多起GPU走私案经新加坡、马来西亚转口；管制后灰色报价一度高于官方数倍。\n影响：国内算力租赁价格难快速回落；对A股是国产替代的情绪催化，落地仍看产能。", "src": "新浪科技"}, {"cat": "财经", "topic": "债券", "t": "储蓄国债11月10日开卖", "s": "3年1.63%、5年1.70%，11月10日起售，额度靠抢", "b": "事实：财政部、央行通知：3年期票面年利率1.63%，最大发行249.04亿元；5年期1.70%，最大发行304.39亿元；11月10日至19日发行，按年付息。\n逻辑：（推演）利率下行期，储蓄国债的优势在锁定而非高息；3年与5年只差7个基点，说明长端下行预期并不激进。\n历史：2020年3年期曾达3.8%、5年3.97%，五年腰斩，是居民资金转向理财与债基的直接原因。\n影响：适合放3—5年确定不用的钱，额度常当日售罄需提前预约；提前兑取要扣手续费并损失部分利息。", "src": "新浪财经 / 财政部"}, {"cat": "财经", "topic": "股票", "t": "全球黑色星期五", "s": "德股跌2%、美股历史性抛售，台股启动稳定基金", "b": "事实：11月6日德国DAX跌2%至25798.89点，英国富时100跌1.80%，法国CAC40跌1.27%；美股遭遇历史性抛售，苹果盘前跌超1%；台股将动用稳定基金；A股“东方”系掀起涨停潮。\n逻辑：（推演）美元指数站上102、美债利率上行压制全球估值；稳定基金是防流动性踩踏的行政工具，改不了趋势。\n历史：2000年台股国安基金、2015年A股救市、2022年英国养老金LDI危机，都是流动性—杠杆共振的典型。\n影响：外围杀估值时高估值成长股弹性最大也最易被砸；现金与红利是缓冲，别在开盘半小时追涨杀跌。", "src": "华尔街见闻 / 百度热搜"}, {"cat": "涨知识", "topic": "其他", "t": "1.5℃红线为何重要", "s": "每多0.1℃，极端天气概率非线性上升", "b": "事实：11月6日“失守1.5℃升温红线将酿成巨灾”登上热搜，讨论聚焦温控目标与极端天气频率，具体报告口径待确认。\n逻辑：（推演）1.5℃不是物理悬崖，而是科学与政治折中的可承受阈值，每多0.1℃极端事件概率非线性上升。\n历史：2015年《巴黎协定》定下远低于2℃、努力限制在1.5℃；2018年IPCC特别报告把它推到前台。\n影响：对普通人是保险、农产品与电价的长期变量；对投资是电网、水利、耐旱种子的长周期主题。", "src": "百度热搜（细节待确认）"}], "text": "《每日世界简报》 2026-11-06（周五）\n\n① 加蓬总统访华    习近平举行欢迎仪式，中非合作再落一子\n② 以色列对美停援震惊    美以关系出现公开裂痕，中东溢价抬头\n③ 希腊沉船59人失踪    60名非法移民仅1人获救，东地中海再酿惨剧\n④ 反跨境腐败法表决通过    6章47条，国家监委牵头，追逃追赃补上国内法拼图\n⑤ 账款披露新规    账期写进债券披露，替中小企业讨“60日付现”\n⑥ 京渝同步松绑住房    从控房价转向稳总量，改善性需求被反复点名\n⑦ 下半年首个暴雪预警    北京发黄色信号，周六雪强达峰，出行与菜价先受影响\n⑧ 2027年9天春节长假    调休拼长假，机票酒店已开始前置涨价\n⑨ 造出最冷人造物质    我国科学家再破纪录，超冷原子是量子技术底座\n⑩ 英伟达芯片被劫    7605万元货物被假卡车拉走，AI芯片黑市链条浮现\n⑪ 储蓄国债11月10日开卖    3年1.63%、5年1.70%，11月10日起售，额度靠抢\n⑫ 全球黑色星期五    德股跌2%、美股历史性抛售，台股启动稳定基金\n⑬ 1.5℃红线为何重要    每多0.1℃，极端天气概率非线性上升\n\n━ 一、国际 ━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n① 加蓬总统访华\n  事实 ｜ 11月6日习近平举行仪式，欢迎加蓬总统恩圭马访华，\n       双方将谈双边关系与中非合作。\n  逻辑 ｜ （推演）加蓬是非洲产油国与锰矿出口国，中方密集接待非洲元首，\n       意在长期锁定矿产与能源。\n  历史 ｜ 2023年加蓬政变后西方暂停部分援助，中国仍维持不干涉内政的合作模式，\n       与以往处理方式一致。\n  影响 ｜ 直接影响小，但锰、铀、原油的长期采购会影响国内钢材与电池成本。\n\n② 以色列对美停援震惊\n  事实 ｜ 11月6日以色列总统称，对美国拟停止军事援助感到震惊；\n       同日以阿拉伯裔政党正推动扳倒内塔尼亚胡。\n  逻辑 ｜ （推演）美国国内政治周期与战事成本上升，\n       让援助从战略承诺变成可议价筹码。\n  历史 ｜ 2016年美以签十年380亿美元军援备忘录，\n       援助历来附带条件，并非无条件赠与。\n  影响 ｜ 中东风险溢价推高油价与航运保险，\n       国内成品油、航空与化工成本跟着波动。\n\n③ 希腊沉船59人失踪\n  事实 ｜ 载60名非法移民的船3日在希腊克里特岛东南海域沉没，\n       截至5日仅1人获救、59人失踪，搜救仍在继续。\n  逻辑 ｜ （推演）东地中海航线因利比亚、埃及局势外溢更拥挤；\n       欧盟把边界外包后，救援与遣返互相推诿。\n  历史 ｜ 2015年4月地中海两起沉船致超700人死亡，\n       此后欧盟—土耳其协议压住东线，中线死亡率反升。\n  影响 ｜ 与国内生活关联弱，但会强化欧洲边境管控议题，\n       间接影响中欧贸易摩擦的节奏。\n\n━ 二、国内政策与民生 ━━━━━━━━━━━━━━━━━━━━━━\n\n④ 反跨境腐败法表决通过\n  事实 ｜ 全国人大常委会11月6日表决通过反跨境腐败法，共6章47条，\n       含机制职责、案件办理与国际合作、廉洁合规、法律责任。\n  逻辑 ｜ （推演）过去追逃靠个案协商，缺国内法授权与跨境取证程序；\n       立法后可对接国际公约，形成固定流程。\n  历史 ｜ 2015年公布百名红通，早期多靠劝返；\n       2018年国家监委成立后才有统一对外办案主体。\n  影响 ｜ 普通人无直接负担，但外贸与跨境电商的境外账户、代理支付\n       合规审查会趋严。\n\n⑤ 账款披露新规\n  事实 ｜ 11月6日交易商协会发文，发行人须披露近一年应付账款余额、\n       账期分布与周转天数，鼓励践行“60日付现承诺”。\n  逻辑 ｜ （推演）大企业用商业信用免费融资，把账期写进债券披露，\n       等于让投资人替中小企业监督。\n  历史 ｜ 2020年《保障中小企业款项支付条例》已定“一般不超60日”，\n       但缺披露口径，执行靠举报。\n  影响 ｜ 若真落地，中小供应商回款变快、现金流改善；\n       大企业营运资金承压。\n\n⑥ 京渝同步松绑住房\n  事实 ｜ 11月6日北京提出2030年城镇住房总量保持稳定、\n       供给结构与需求更适配，鼓励刚性与改善性需求；\n       同日重庆出台商品住房销售新政。\n  逻辑 ｜ （推演）政策目标从控房价转向稳总量、调结构，\n       说明重心已由抑需求变为防失速。\n  历史 ｜ 2016年“930”、2017年“317”是收紧起点；\n       2022年以来松绑超千次，成交修复仍弱于预期。\n  影响 ｜ 想换房的可等细则（税费、二套认定）；\n       城市分化会更大；地产链是情绪利好，仍看销售数据。\n\n━ 三、社会与生活 ━━━━━━━━━━━━━━━━━━━━━━━━\n\n⑦ 下半年首个暴雪预警\n  事实 ｜ 11月6日18时中央气象台发布暴雪蓝色预警，为下半年首个；\n       北京同步发布黄色预警，7日中午至8日上午多区大雪到暴雪，\n       局地积雪可达8厘米以上。\n  逻辑 ｜ （推演）11月上旬华北暴雪，是暖湿气流异常北推叠加冷空气南下；\n       真正的风险点在结冰与早高峰重叠。\n  历史 ｜ 2021年11月6—8日华北罕见暴雪致交通瘫痪；\n       2012年北京“7·21”暴露过应急调度短板。\n  影响 ｜ 周末避开山区与高速；京津冀快递、蔬菜运输或延迟1—2天，\n       菜价短期小涨。\n\n⑧ 2027年9天春节长假\n  事实 ｜ 2027年放假安排公布，春节形成9天超长假期，\n       旅游平台已出现除夕前一日机票下单。\n  逻辑 ｜ （推演）用调休拼长假，是用集中假期刺激服务消费，\n       把分散休息日换成可出行的整块时间。\n  历史 ｜ 1999年设黄金周，2008年增清明、五一、中秋小长假，\n       每次调整都伴随出行峰值与承载争议。\n  影响 ｜ 除夕前一日机票、热门城市酒店会先涨；\n       景区民宿弹性大，但前后周末要连上更长的班。\n\n━ 四、科技与新知 ━━━━━━━━━━━━━━━━━━━━━━━━\n\n⑨ 造出最冷人造物质\n  事实 ｜ 澎湃新闻11月6日报道，我国科学家造出目前已知最冷的人造物质，\n       成果已发表，具体温度与装置以论文为准。\n  逻辑 ｜ （推演）超冷原子是量子计算、原子钟与精密测量的底座；\n       温度再低一个量级，相干时间更长、噪声更低。\n  历史 ｜ 1995年实现玻色—爱因斯坦凝聚，2001年获诺奖；\n       中国2010年后靠超冷费米气体追赶。\n  影响 ｜ 短期无消费级产品，长期影响量子传感、导航\n       与高端仪器的进口替代。\n\n⑩ 英伟达芯片被劫\n  事实 ｜ 加州奥克兰警方调查英伟达硬件被盗案，\n       涉值1140万美元（约7605万元），货物被伪装成食品运输的\n       卡车接走后失踪。\n  逻辑 ｜ （推演）AI芯片黑市已形成订单—伪造承运—跨境转卖链条，\n       物流是验证最薄弱的一环。\n  历史 ｜ 2023年以来多起GPU走私案经新加坡、马来西亚转口；\n       管制后灰色报价一度高于官方数倍。\n  影响 ｜ 国内算力租赁价格难快速回落；\n       对A股是国产替代的情绪催化，落地仍看产能。\n\n━ 五、跟你钱袋子有关 ━━━━━━━━━━━━━━━━━━━━━━\n\n⑪ 储蓄国债11月10日开卖\n  事实 ｜ 财政部、央行通知：3年期票面年利率1.63%，最大发行249.04亿元；\n       5年期1.70%，最大发行304.39亿元；\n       11月10日至19日发行，按年付息。\n  逻辑 ｜ （推演）利率下行期，储蓄国债的优势在锁定而非高息；\n       3年与5年只差7个基点，说明长端下行预期并不激进。\n  历史 ｜ 2020年3年期曾达3.8%、5年3.97%，五年腰斩，\n       是居民资金转向理财与债基的直接原因。\n  影响 ｜ 适合放3—5年确定不用的钱，额度常当日售罄需提前预约；\n       提前兑取要扣手续费并损失部分利息。\n\n⑫ 全球黑色星期五\n  事实 ｜ 11月6日德国DAX跌2%至25798.89点，英国富时100跌1.80%，\n       法国CAC40跌1.27%；美股遭遇历史性抛售，苹果盘前跌超1%；\n       台股将动用稳定基金；A股“东方”系掀起涨停潮。\n  逻辑 ｜ （推演）美元指数站上102、美债利率上行压制全球估值；\n       稳定基金是防流动性踩踏的行政工具，改不了趋势。\n  历史 ｜ 2000年台股国安基金、2015年A股救市、2022年英国养老金LDI危机，\n       都是流动性—杠杆共振的典型。\n  影响 ｜ 外围杀估值时高估值成长股弹性最大也最易被砸；\n       现金与红利是缓冲，别在开盘半小时追涨杀跌。\n\n━ 六、涨知识一分钟 ━━━━━━━━━━━━━━━━━━━━━━━\n\n⑬ 1.5℃红线为何重要\n  事实 ｜ 11月6日“失守1.5℃升温红线将酿成巨灾”登上热搜，\n       讨论聚焦温控目标与极端天气频率，具体报告口径待确认。\n  逻辑 ｜ （推演）1.5℃不是物理悬崖，而是科学与政治折中的\n       可承受阈值，每多0.1℃极端事件概率非线性上升。\n  历史 ｜ 2015年《巴黎协定》定下远低于2℃、努力限制在1.5℃；\n       2018年IPCC特别报告把它推到前台。\n  影响 ｜ 对普通人是保险、农产品与电价的长期变量；\n       对投资是电网、水利、耐旱种子的长周期主题。\n"}];
